\label{TheSetting}
Fix $d,N\in \mathbb{N}_+$, $s\in \mathbb{N}$, $M>0$, distinct sites $X_1,\dots,X_N\in \mathbb{R}^d$, an (unknown) $f\in \dot{C}^{s,1}(\mathbb{R}^d)$, any polynomials $P_1,\dots,P_N\in \mathbb{R}[x_1,\dots,x_d]$ of degree at-most $s$ such that: for each $n\in [N]$
\begin{equation}
\label{eq:training_data}
P_n = J_{X_n}^s f
\qquad
\mbox{ and } \operatorname{Lip}(D^s\,f)\le M
.
\end{equation}

\label{cor:full-Cs1-control}
In the setting of Theorem~\ref{thrm:main}, suppose that $\mathbb X^N\subseteq[0,1]^d$. Then, for every $s\in\mathbb N$,
\begin{equation}
\label{eq:full-Cs1-control}
 \|F\|_{C^{s,1}([0,1]^d)}
 \le \mathrm e^{\sqrt d}\left(
 \min_{i\in[N]}\sum_{r=0}^s\|D^rP_i(X_i)\|_{\mathrm{op}}
 +K_{d,s}M\right).
\end{equation}
In particular, the bound has no dependence on the sample size or separation beyond the displayed measured jet values.

\label{thrm:complexity}
Fix $d,N,s\in\mathbb N_+$ with $s\ge2$, $M>0$, pairwise distinct $X_1,\ldots,X_N\in\mathbb R^d$, polynomials $P_i\in\mathbb R[x_1,\ldots,x_d]$, $i\in[N]$, of degree at most $s$, $D\ge1$, and $\mu\in\Delta_N^\circ$. Set $q\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}2s+\lceil\log_2D\rceil+2$ and $U\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\mathbb R^d\setminus\{X_1,\ldots,X_N\}$. There exists a bounded-fan-in $\mathbb G$-circuit $\widehat{\mathcal C}_{\operatorname{ext}}$, with $d$ input vertices and lifting channel $I_d$, which computes $F_{\operatorname{ext}}$; i.e.\
\[
    f_{\hat{\mathcal{C}}_{\operatorname{ext}}}(x) = F_{\operatorname{ext}}(x)
\qquad
\mbox{ for all } x\in \mathbb{R}^d
\]
satisfying:
\begin{enumerate}[label=(\roman*), ref=(\roman*)]
    \item \label{eq:closed-form-circuit-size}
    \textbf{Storage Cost:} Size of $\mathcal O_s(Nd^s)$,
    \item \label{eq:closed-form-circuit-depth}
    \textbf{Parallel Query Time:} $\mathcal O_s(\log(d+N))$,
    \item \label{eq:closed-form-circuit-width}
    \textbf{Parallelism Used:} Width of $\mathcal O_s(Nd^s)$.
\end{enumerate}

\label{thrm:complexity__Assembly}
Fix $d,s\in\mathbb N_+$ with $s\ge2$. There exists a uniform exact-real word-RAM algorithm $\texttt{Compile-Circuit}$ (Algorithm~\ref{alg:compile-circuit})\footnote{The program depends only on $d,s$.} such that, for every input satisfying Data Format~\ref{dataformat} 
on a word length 

of $\mathcal O_{d,s}\!\bigl(\log(q+N)\bigr)$ 
, the algorithm returns a $\mathbb G$-circuit $\widehat{\mathcal C}_{\operatorname{ext}}$\footnote{Encoded by the decorated adjacency representation $\operatorname{Adj}(\widehat{\mathcal C}_{\operatorname{ext}})$ specified in~\eqref{eq:compiler-record}.} satisfying Theorem~\ref{thrm:complexity} with $D=2^{q-2s-2}$. Moreover,
\[
\begin{aligned}
\operatorname{Work}(\texttt{Compile-Circuit})&=\mathcal O_s(Nd^s),\\
\operatorname{OutputStorage}(\texttt{Compile-Circuit})&=\mathcal O_s(Nd^s).
\end{aligned}
\]

\label{prop:Carlos}
Let $d,N\in \mathbb{N}_+$, and $s=1$; then, for every $x\in\mathbb{R}^d$
\[
\begin{aligned}
    F(x)
& = 
    \operatorname{conv}\!\left(
        g
    \right)(x)
    -\frac{M}{2}|x|^2,
\\
g(y)
&  \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} 
        \min_{1\le i\le N}
        \left\{P_i(y)+\frac{M}{2}|y-X_i|^2\right\}
        +\frac{M}{2}|y|^2
.
\end{aligned}
\]
Here $\operatorname{conv}$ denotes the lower-semicontinuous convex envelope.

The data and the global witness satisfy \eqref{eq:training_data}; the geometry weights and their certificate remain fixed as in \eqref{eq:doubling}. 
For the higher-order part, fix an arbitrary $\vartheta\in[0,1]$ and use $F_\vartheta$ from~\eqref{eq:entropy-variance-extension__primal___SITES}--\eqref{eq:entropy-variance-extension__primal}. The parameter is fixed throughout spatial differentiation, and every estimate below is uniform in this fixed $\vartheta$. The original reconstruction is recovered at $\vartheta=1$ by~\eqref{eq:entropy-variance-extension__specialization}.
For a map $u$ on a set $\Omega$ into a normed finite-dimensional space, $\operatorname{Lip}_\Omega(u)$ denotes the supremum of $\|u(x)-u(y)\|/|x-y|$ over distinct $x,y\in\Omega$. Derivatives of vector- or tensor-valued maps carry the operator norm induced by the specified codomain norm. Partial tensor contractions retain the unfilled slots. Write $\mathrm{e}=\exp(1)$ and, for $a=X_i$, $P_a=P_i$. The distance functions $r_i$ and $\rho_{\mathbb{X}^N}$ below are defined for all $x\in\mathbb{R}^d$:
\begin{equation}
\label{eq:three-aux-geometry}
 m \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} s+1,\qquad r_i(x) \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} |x-X_i|,\qquad
 \rho_{\mathbb{X}^N}(x) \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} \min_{i\in[N]}r_i(x),\qquad
 S_\gamma(x) \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} \sum_{i=1}^N\mu_i r_i(x)^{-\gamma}
\end{equation}
(where, clearly, the sum $S_\gamma$ is defined for $x\notin\mathbb{X}^N$ and $\gamma\ge0$).
For $a\in\mathbb{X}^N$ and $r>0$, let $B_{\mathbb{X}^N}(a,r) \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} \{X_i:|X_i-a|<r\}$ and identify the fixed vector $\mu$ with the atomic measure $\mu(A) \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} \sum_{X_i\in A}\mu_i$. The definitions in \S\ref{s:TheFormula} implies that:
if $R^p=\frac{S_{q-p}}{S_q}$, $m-p=-\beta$, and $s\ge2 $ then 
\begin{equation}
\label{eq:three-aux-parameters}
(\beta,p,q)=\bigl(s-1,2s,2s+\lceil\log_2D\rceil+2\bigr).
\end{equation}
Here $q-p\ge2$, all distances are positive off the sites, and $R>0$. In particular the entropy convention makes the objective continuous on the compact simplex: each summand $\lambda_i\log\lambda_i$ extends continuously at zero, and the other terms are polynomials in $\lambda$. Indeed, writing $t=\mathrm{e}^{-u}$ gives $|t\log t|=u\mathrm{e}^{-u}\to0$ as $t\downarrow0$, since $\mathrm{e}^u\ge u^2/2$ for $u>0$. A coordinatewise convergent subsequence of a minimizing sequence therefore attains the minimum. No value of a singular helper function is assigned at a site. In the higher-order proof $\mathfrak h_\vartheta(x)$ will denote the normalized optimal value associated with $F_\vartheta$; it is distinct from the fill radius $h$.


To obtain constants independent of how the sites are distributed, we construct positive weights for which doubling a ball's radius increases its total weight by at most a factor depending only on $d$. The next two lemmas achieve this by transferring controlled weights between successively finer subsets of the sites.

\begin{lemma}
\label{lem:three-weight-transfer}
Fix $d\in\mathbb N_+$ and $r>0$, and put $A \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} 16$ and $B \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} A^{2d}$. Let $S,T\subset\mathbb{R}^d$ be finite nonempty sets, with distinct points of $S$ at distance at least $r$ and distinct points of $T$ at distance at least $r/A$. Suppose that $\varphi:T\to S$ is onto and $|t-\varphi(t)|<r$ for every $t\in T$. Let $(\nu_e)_{e\in S}$ be positive weights of sum one satisfying
\begin{equation}
\label{eq:three-parent-weight-comparison}
 \nu_e\le B^2\nu_{e'}\qquad
 (e,e'\in S,\ |e-e'|<4r).
\end{equation}
Then there are positive weights $(\nu'_t)_{t\in T}$ of sum one such that
\begin{equation}
\label{eq:three-child-weight-bounds}
 B^{-1}\nu_{\varphi(t)}\le\nu'_t\le\nu_{\varphi(t)},\qquad
 \nu'_t\le B^2\nu'_{t'}\quad
 (t,t'\in T,\ |t-t'|<4r/A).
\end{equation}
Moreover, there are numbers $\pi_{e,t}\ge0$ with row sums $\nu_e$, column sums $\nu'_t$, and $\pi_{e,t}>0$ implies that 
\begin{equation}
\label{eq:three-one-step-transport}
 |e-t|<(1+4/A)r.
\end{equation}
\end{lemma}
\begin{proof}
Write $\mathbb B(z,\rho)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\{y\in\mathbb R^d:|y-z|<\rho\}$, $v_d\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\mathcal L^d(\mathbb B(0,1))>0$, $T_e\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\varphi^{-1}(\{e\})$, $n_e\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}|T_e|$, and $w_t\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\nu_{\varphi(t)}$. For $e\in S$, surjectivity and separation give
\[
\begin{gathered}
1\le n_e,\qquad \mathbb B(t,r/(2A))\cap\mathbb B(t',r/(2A))=\varnothing\quad(t,t'\in T_e,\ t\ne t'),\\
\bigcup_{t\in T_e}\mathbb B(t,r/(2A))\subseteq\mathbb B(e,r+r/(2A)),\\
n_ev_d(r/(2A))^d\le v_d(r+r/(2A))^d,\qquad n_e\le(2A+1)^d<A^{2d}=B.
\end{gathered}
\]
For $a,b\in T$, \eqref{eq:three-parent-weight-comparison} yields
\[
\begin{aligned}
|a-b|<8r/A&\Longrightarrow |\varphi(a)-\varphi(b)|\le|\varphi(a)-a|+|a-b|+|b-\varphi(b)|\\
&\hspace{37mm}<(2+8/A)r<4r\Longrightarrow w_a\le B^2w_b.
\end{aligned}
\]

Enumerate $\mathcal E\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\{\{a,b\}:a,b\in T,\ a\ne b,\ |a-b|<4r/A\}=\{E_1,\ldots,E_L\}$ without repetition, allowing $L=0$, and put $u_t^0\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} w_t/n_{\varphi(t)}$. Recursively, for $1\le k\le L$ and $E_k=\{a,b\}$, set $u^k=u^{k-1}$ if $\max(u_a^{k-1},u_b^{k-1})\le B^2\min(u_a^{k-1},u_b^{k-1})$. Otherwise, let $(g_k,h_k)$ be the ordering of $E_k$ satisfying $u_{g_k}^{k-1}>B^2u_{h_k}^{k-1}$ and set
\begin{equation}
\label{eq:three-pair-weight-update}
\begin{aligned}
\delta_k&\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\frac{u_{g_k}^{k-1}-B^2u_{h_k}^{k-1}}{B^2+1},&u_t^k&\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} u_t^{k-1}+\delta_k\bigl(\mathbf1_{\{t=h_k\}}-\mathbf1_{\{t=g_k\}}\bigr),\\
u_{g_k}^k&=\frac{B^2(u_{g_k}^{k-1}+u_{h_k}^{k-1})}{B^2+1},&u_{h_k}^k&=\frac{u_{g_k}^{k-1}+u_{h_k}^{k-1}}{B^2+1}.
\end{aligned}
\end{equation}
Let $\mathcal I\subseteq\{1,\ldots,L\}$ consist of the nonidentity updates. We prove by induction that
\begin{equation}
\label{eq:three-transfer-intervals}
0<w_t/B\le u_t^k\le w_t\quad(t\in T),\qquad \sum_{t\in T}u_t^k=1\qquad(0\le k\le L).
\end{equation}
At $k=0$, $1\le n_e<B$ and $\sum_{t\in T}u_t^0=\sum_{e\in S}n_e\nu_e/n_e=1$. For $k\in\mathcal I$, abbreviate $g=g_k$, $h=h_k$. The inductive hypothesis and \eqref{eq:three-pair-weight-update} imply $0<\delta_k<u_g^{k-1}$, $u_g^k=B^2u_h^k$, and
\[
\begin{aligned}
w_g/B&\le Bw_h\le B^2u_h^{k-1}\le B^2u_h^k=u_g^k\le u_g^{k-1}\le w_g,\\
w_h/B&\le u_h^{k-1}\le u_h^k=u_g^k/B^2\le u_g^{k-1}/B^2\le w_g/B^2\le w_h,\\
\sum_{t\in T}u_t^k&=\sum_{t\in T}u_t^{k-1}+\delta_k(1-1)=1.
\end{aligned}
\]
The remaining coordinates and the steps $k\notin\mathcal I$ are unchanged.

Put $\mathcal Q_k\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\{\{a,b\}\in\mathcal E:\max(u_a^k,u_b^k)\le B^2\min(u_a^k,u_b^k)\}$. Fix $k\in\mathcal I$, $g=g_k$, $h=h_k$, and $t\in T\setminus\{g,h\}$. For $\{g,t\}\in\mathcal Q_{k-1}$, $|t-h|\le|t-g|+|g-h|<8r/A$, so
\[
u_g^k\le u_g^{k-1}\le B^2u_t^{k-1}=B^2u_t^k,\qquad u_t^k\le w_t\le B^2w_h\le Bu_g^k\le B^2u_g^k.
\]
For $\{h,t\}\in\mathcal Q_{k-1}$, $|g-t|\le|g-h|+|h-t|<8r/A$, so
\[
u_t^k=u_t^{k-1}\le B^2u_h^{k-1}\le B^2u_h^k,\qquad u_h^k=u_g^k/B^2\le w_g/B^2\le w_t\le Bu_t^k\le B^2u_t^k.
\]
Moreover, $u_g^k=B^2u_h^k$ and $E\cap\{g,h\}=\varnothing$ implies $(u_t^k)_{t\in E}=(u_t^{k-1})_{t\in E}$. Consequently,
\[
k\notin\mathcal I\ \Longrightarrow\ \mathcal Q_k=\mathcal Q_{k-1}\ni E_k,\qquad \mathcal Q_k\supseteq\mathcal Q_{k-1}\cup\{E_k\}\quad(1\le k\le L),\qquad \mathcal Q_L\supseteq\bigcup_{k=1}^L\{E_k\}=\mathcal E.
\]
Set $\nu'_t\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} u_t^L$. Then $\mathcal Q_L=\mathcal E$, $B\ge256>1$, and~\eqref{eq:three-transfer-intervals} give
\[
\sum_{t\in T}\nu'_t=1,\qquad 0<B^{-1}\nu_{\varphi(t)}\le\nu'_t\le\nu_{\varphi(t)},\qquad \nu'_t\le B^2\nu'_{t'}\quad(|t-t'|<4r/A),
\]
where $t=t'$ uses $B^2\ge1$.

Define $a_{gh}\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\sum_{k\in\mathcal I:(g_k,h_k)=(g,h)}\delta_k$ for $g,h\in T$ and $\mathcal D\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\{(g,h)\in T^2:a_{gh}>0\}$. For every $k\in\mathcal I$, \eqref{eq:three-transfer-intervals} gives
\begin{equation}
\label{eq:three-transfer-parent-decrease}
w_{g_k}\ge u_{g_k}^{k-1}>B^2u_{h_k}^{k-1}\ge Bw_{h_k}.
\end{equation}
If $(g,h),(h,t)\in\mathcal D$, then $|g-t|\le|g-h|+|h-t|<8r/A$ and $w_g>Bw_h>B^2w_t$, contradicting $w_g\le B^2w_t$. Hence
\[
a_{gh}a_{ht}=0\quad(g,h,t\in T),\qquad O_t\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\sum_{h\in T}a_{th},\quad I_t\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\sum_{g\in T}a_{gt},\quad O_tI_t=\sum_{g,h\in T}a_{gt}a_{th}=0.
\]
Summing \eqref{eq:three-pair-weight-update} over $k$ gives $u_t^L=u_t^0-O_t+I_t$. In particular,
\[
c_t\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} u_t^0-O_t=\begin{cases}u_t^0,&O_t=0,\\u_t^L,&O_t>0,\end{cases}\qquad c_t>0,\qquad \pi_{e,t}\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\mathbf1_{\{e=\varphi(t)\}}c_t+\sum_{g\in T:\varphi(g)=e}a_{gt}\ge0.
\]
For $e\in S$ and $t\in T$,
\[
\begin{aligned}
\sum_{t\in T}\pi_{e,t}&=\sum_{t\in T_e}(u_t^0-O_t)+\sum_{g\in T_e}\sum_{t\in T}a_{gt}=\sum_{t\in T_e}u_t^0=\nu_e,\\
\sum_{e\in S}\pi_{e,t}&=c_t+\sum_{g\in T}a_{gt}=u_t^0-O_t+I_t=u_t^L=\nu'_t.
\end{aligned}
\]
Finally,
\[
\begin{aligned}
\pi_{e,t}>0&\ \Longrightarrow\ (e=\varphi(t))\ \lor\ (\exists g\in T:\ e=\varphi(g),\ (g,t)\in\mathcal D),\\
e=\varphi(t)&\ \Longrightarrow\ |e-t|<r<(1+4/A)r,\\
e=\varphi(g),\ (g,t)\in\mathcal D&\ \Longrightarrow\ |e-t|\le|\varphi(g)-g|+|g-t|<r+4r/A=(1+4/A)r.
\end{aligned}
\]
\end{proof}

\begin{lemma}[Positive Geometry Weights with a Dimension-Only Certificate]
\label{lem:three-doubling-weights}
For every $d,N\in\mathbb N_+$ and distinct sites $X_1,\ldots,X_N\in\mathbb{R}^d$, there exists $\mu\in\Delta_N^\circ$ satisfying \eqref{eq:doubling} with $D=2^{46d}$.
\end{lemma}
\begin{proof}
We use the finite redistribution construction of~\cite{VolbergKonyagin1988}. If $N=1$, set $\mu_1=1$; for every $r>0$, both sums in~\eqref{eq:doubling} equal $1\le2^{46d}$. Suppose $N\ge2$. Put $c\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}4(1+\operatorname{diam}(\mathbb X^N))$, $Y_i\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}(X_i-X_1)/c$, and $X\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\{Y_i:i\in[N]\}$. Then
\[
c>0,\qquad |Y_i-Y_k|=c^{-1}|X_i-X_k|,\qquad \operatorname{diam}(X)=\frac{\operatorname{diam}(\mathbb X^N)}{4(1+\operatorname{diam}(\mathbb X^N))}<\frac14.
\]
Write $\mathcal B(z,t)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\{y\in\mathbb R^d:|y-z|<t\}$ and $B_X(z,t)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} X\cap\mathcal B(z,t)$. Set $A\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}16$, $B\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} A^{2d}$, $r_j\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} A^{-j}$ for $j\in\mathbb N_0$, $\sigma\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\min_{i\ne k}|Y_i-Y_k|>0$, and $J\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\min\{j\in\mathbb N_0:r_j<\sigma\}<\infty$.

For $0\le j\le J$, define $S_j^{(0)}\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\varnothing$ and, with $\operatorname{dist}(z,\varnothing)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\infty$,
\[
S_j^{(i)}\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\begin{cases}S_j^{(i-1)}\cup\{Y_i\},&\operatorname{dist}(Y_i,S_j^{(i-1)})\ge r_j,\\S_j^{(i-1)},&\operatorname{dist}(Y_i,S_j^{(i-1)})<r_j,\end{cases}\qquad i\in[N],\qquad S_j\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} S_j^{(N)}.
\]
For $i<k$ with $Y_i,Y_k\in S_j$, the insertion rule gives $|Y_i-Y_k|\ge r_j$; $Y_i\in S_j$ gives $\operatorname{dist}(Y_i,S_j)=0<r_j$, whereas $Y_i\notin S_j$ gives $\operatorname{dist}(Y_i,S_j)\le\operatorname{dist}(Y_i,S_j^{(i-1)})<r_j$. Consequently,
\[
\min_{z\in S_j}|y-z|<r_j\quad(y\in X),\qquad S_0=\{Y_1\},\qquad r_J<\sigma\Longrightarrow S_J=X.
\]
Set $S_j\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} X$ for $j>J$. For every $j\in\mathbb N_0$, let $\varphi_j(t)$ be the least-indexed minimizer of $e\mapsto|t-e|$ on $S_j$, for $t\in S_{j+1}$. Thus $|t-\varphi_j(t)|<r_j$, and $\varphi_j=\operatorname{Id}_X$ for $j\ge J$. For $e\in S_j$, choose $t\in S_{j+1}$ with $|t-e|<r_{j+1}$; then
\[
|e-\varphi_j(t)|\le|e-t|+|t-\varphi_j(t)|\le2|e-t|<2r_{j+1}=\frac{r_j}{8}<r_j\Longrightarrow\varphi_j(t)=e\Longrightarrow\varphi_j(S_{j+1})=S_j.
\]

Set $\nu_0(Y_1)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}1$; then $\nu_0(Y_1)=1\le B^2\nu_0(Y_1)$. Apply Lemma~\ref{lem:three-weight-transfer} inductively with
\[
(S,T,r,\varphi,\nu)=(S_j,S_{j+1},r_j,\varphi_j,\nu_j)\quad(0\le j<J),\qquad 4r_j/A=4r_{j+1}.
\]
Its conclusions give positive probability weights $\nu_j$ on $S_j$, $0\le j\le J$, satisfying
\begin{equation}
\label{eq:three-net-weight-properties}
\begin{gathered}
\sum_{e\in S_j}\nu_j(e)=1,\qquad \nu_j(e)>0,\qquad \nu_j(e)\le B^2\nu_j(e')\quad(e,e'\in S_j,\ |e-e'|<4r_j),\\
B^{-1}\nu_j(\varphi_j(t))\le\nu_{j+1}(t)\le\nu_j(\varphi_j(t))\quad(0\le j<J,\ t\in S_{j+1}),
\end{gathered}
\end{equation}
and, for $0\le j<J$, numbers $\pi_j(e,t)\ge0$ satisfying
\[
\begin{gathered}
\sum_{t\in S_{j+1}}\pi_j(e,t)=\nu_j(e),\qquad \sum_{e\in S_j}\pi_j(e,t)=\nu_{j+1}(t),\\
\pi_j(e,t)>0\Longrightarrow|e-t|<Cr_j,\qquad C\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}1+4/A.
\end{gathered}
\]
Put $\mu(y)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\nu_J(y)$ for $y\in X$ and $\nu_j\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\mu$ for $j\ge J$. Since $r_j\le r_J$, for $e,e'\in X$,
\[
\begin{gathered}
|e-e'|<4r_j\Longrightarrow|e-e'|<4r_J\Longrightarrow\nu_j(e)=\nu_J(e)\le B^2\nu_J(e')=B^2\nu_j(e'),\\
B^{-1}\nu_j(\varphi_j(t))\le\nu_{j+1}(t)=\nu_j(\varphi_j(t)).
\end{gathered}
\]

Set
\begin{equation}
\label{eq:three-net-transport-constants}
C_1\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\frac{1+4/A}{1-1/A}=\frac43,\qquad \frac1{1-1/A}=\frac{16}{15},\qquad C+C_1/A=C_1.
\end{equation}
For $j\ge J$, put $\Pi_j(e,y)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\mu(e)\mathbf1_{\{e=y\}}$. For $j=J-1,\ldots,0$, recursively put
\[
\Pi_j(e,y)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\sum_{t\in S_{j+1}}\pi_j(e,t)\frac{\Pi_{j+1}(t,y)}{\nu_{j+1}(t)}\qquad(e\in S_j,\ y\in X).
\]
For $j\ge J$,
\[
\begin{gathered}
\sum_{y\in X}\Pi_j(e,y)=\mu(e)=\nu_j(e),\qquad\sum_{e\in X}\Pi_j(e,y)=\mu(y),\\
\Pi_j(e,y)>0\Longrightarrow e=y\Longrightarrow|e-y|=0<C_1r_j.
\end{gathered}
\]
Since every $\nu_{j+1}(t)>0$, the backward induction step is
\[
\begin{aligned}
\sum_{y\in X}\Pi_j(e,y)&=\sum_{t\in S_{j+1}}\frac{\pi_j(e,t)}{\nu_{j+1}(t)}\sum_{y\in X}\Pi_{j+1}(t,y)=\sum_{t\in S_{j+1}}\pi_j(e,t)=\nu_j(e),\\
\sum_{e\in S_j}\Pi_j(e,y)&=\sum_{t\in S_{j+1}}\frac{\Pi_{j+1}(t,y)}{\nu_{j+1}(t)}\sum_{e\in S_j}\pi_j(e,t)=\sum_{t\in S_{j+1}}\Pi_{j+1}(t,y)=\mu(y),\\
\Pi_j(e,y)>0&\Longrightarrow\exists t\in S_{j+1}:\ \pi_j(e,t)\Pi_{j+1}(t,y)>0\\
&\Longrightarrow|e-y|\le|e-t|+|t-y|<Cr_j+C_1r_{j+1}=C_1r_j.
\end{aligned}
\]

Fix $x\in X$ and $r>0$, and write $\mu(E)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\sum_{y\in E}\mu(y)$ for $E\subseteq X$. If $r\ge1/2$, then $|y-x|\le\operatorname{diam}(X)<1/4<r$ for every $y\in X$, so $\mu(B_X(x,2r))=\mu(B_X(x,r))=1$. If $0<r<1/2$, put $j_0\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\max\{j\in\mathbb N_0:r_j\ge2r\}$ and $j_1\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\min\{j\in\mathbb N_0:r_j\le r\}$. Since $r_0=1>2r>r>0$ and $r_j\downarrow0$, these indices exist with $j_1\ge1$; their extremal properties give
\begin{equation}
\label{eq:three-net-scale-indices}
\begin{gathered}
r_{j_0}\ge2r>r_{j_0+1}=r_{j_0}/A,\qquad r_{j_1}\le r<r_{j_1-1}=Ar_{j_1},\qquad j_0<j_1,\\
2r\le r_{j_0}<2Ar,\qquad r/A<r_{j_1}\le r,\qquad A^{j_1-j_0}=r_{j_0}/r_{j_1}<2A^2.
\end{gathered}
\end{equation}
Choose $g\in S_{j_1+1}$ with $|g-x|<r_{j_1+1}$, set $g_{j_1+1}\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} g$, and recursively set $g_j\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\varphi_j(g_{j+1})$ for $j_0\le j\le j_1$. Then
\begin{equation}
\label{eq:three-net-ancestor-distance}
|g_{j_0}-x|\le|g-x|+\sum_{j=j_0}^{j_1}|g_j-g_{j+1}|<\sum_{j=j_0}^{j_1+1}r_j\le\frac{r_{j_0}}{1-1/A}.
\end{equation}
Writing $h\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} j_1+1$, we have
\[
\Pi_h(g,y)>0\Longrightarrow|y-x|\le|y-g|+|g-x|<(C_1+1)r_h\le\frac{C_1+1}{A}r=\frac7{48}r<r.
\]
Hence
\begin{equation}
\label{eq:three-net-inner-mass}
\mu(B_X(x,r))=\sum_{e\in S_h}\sum_{y\in B_X(x,r)}\Pi_h(e,y)\ge\sum_{y\in B_X(x,r)}\Pi_h(g,y)=\sum_{y\in X}\Pi_h(g,y)=\nu_h(g)>0.
\end{equation}

Set $E_0\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\{e\in S_{j_0}:|e-x|<2r+C_1r_{j_0}\}$. For $y\in B_X(x,2r)$,
\[
\Pi_{j_0}(e,y)>0\Longrightarrow|e-x|\le|e-y|+|y-x|<C_1r_{j_0}+2r\Longrightarrow e\in E_0.
\]
For $e\in E_0$, \eqref{eq:three-net-scale-indices} and~\eqref{eq:three-net-ancestor-distance} give
\[
|e-g_{j_0}|\le|e-x|+|x-g_{j_0}|<\left(1+C_1+\frac1{1-1/A}\right)r_{j_0}=\frac{17}{5}r_{j_0}<4r_{j_0}.
\]
Since $|e-e'|\ge r_{j_0}$ for distinct $e,e'\in E_0$, the balls $\mathcal B(e,r_{j_0}/2)$ are pairwise disjoint and their union lies in $\mathcal B(g_{j_0},9r_{j_0}/2)$. Thus, with $\omega_d\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}|\mathcal B(0,1)|>0$ denoting Lebesgue volume,
\[
|E_0|\omega_d(r_{j_0}/2)^d=\left|\bigcup_{e\in E_0}\mathcal B(e,r_{j_0}/2)\right|\le\omega_d(9r_{j_0}/2)^d\Longrightarrow|E_0|\le9^d\le12^d.
\]
Consequently, \eqref{eq:three-net-weight-properties} gives
\begin{equation}
\label{eq:three-net-outer-mass}
\mu(B_X(x,2r))=\sum_{e\in E_0}\sum_{y\in B_X(x,2r)}\Pi_{j_0}(e,y)\le\sum_{e\in E_0}\nu_{j_0}(e)\le12^dB^2\nu_{j_0}(g_{j_0}).
\end{equation}
The parent--child bounds and~\eqref{eq:three-net-scale-indices} imply
\[
\nu_{j_0}(g_{j_0})=\nu_h(g)\prod_{j=j_0}^{h-1}\frac{\nu_j(g_j)}{\nu_{j+1}(g_{j+1})}\le B^{h-j_0}\nu_h(g),\qquad B^{j_1-j_0}=\bigl(A^{j_1-j_0}\bigr)^{2d}\le2^{2d}B^2.
\]
Using~\eqref{eq:three-net-inner-mass} and~\eqref{eq:three-net-outer-mass}, we obtain
\begin{equation}
\label{eq:three-dimension-doubling-certificate}
\begin{aligned}
\mu(B_X(x,2r))&\le12^dB^{j_1-j_0+3}\nu_h(g)\\
&\le12^dB^5 2^{2d}\mu(B_X(x,r))=\left(\frac34\right)^d2^{46d}\mu(B_X(x,r))\le2^{46d}\mu(B_X(x,r)).
\end{aligned}
\end{equation}
Finally, set $\mu_i\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\mu(Y_i)$ for $i\in[N]$. Then $\mu_i>0$, $\sum_i\mu_i=1$, and, for every $i\in[N]$ and $\rho>0$,
\[
\sum_{\substack{k\in[N]\\|X_k-X_i|<2\rho}}\mu_k=\mu(B_X(Y_i,2\rho/c))\le2^{46d}\mu(B_X(Y_i,\rho/c))=2^{46d}\sum_{\substack{k\in[N]\\|X_k-X_i|<\rho}}\mu_k.
\]
\end{proof}

\label{lem:three-weight-transfer}
Fix $d\in\mathbb N_+$ and $r>0$, and put $A \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} 16$ and $B \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} A^{2d}$. Let $S,T\subset\mathbb{R}^d$ be finite nonempty sets, with distinct points of $S$ at distance at least $r$ and distinct points of $T$ at distance at least $r/A$. Suppose that $\varphi:T\to S$ is onto and $|t-\varphi(t)|<r$ for every $t\in T$. Let $(\nu_e)_{e\in S}$ be positive weights of sum one satisfying
\begin{equation}
\label{eq:three-parent-weight-comparison}
 \nu_e\le B^2\nu_{e'}\qquad
 (e,e'\in S,\ |e-e'|<4r).
\end{equation}
Then there are positive weights $(\nu'_t)_{t\in T}$ of sum one such that
\begin{equation}
\label{eq:three-child-weight-bounds}
 B^{-1}\nu_{\varphi(t)}\le\nu'_t\le\nu_{\varphi(t)},\qquad
 \nu'_t\le B^2\nu'_{t'}\quad
 (t,t'\in T,\ |t-t'|<4r/A).
\end{equation}
Moreover, there are numbers $\pi_{e,t}\ge0$ with row sums $\nu_e$, column sums $\nu'_t$, and $\pi_{e,t}>0$ implies that 
\begin{equation}
\label{eq:three-one-step-transport}
 |e-t|<(1+4/A)r.
\end{equation}

\label{lem:three-taylor}
Fix $d\in\mathbb{N}_+$, $s\in\mathbb N$, and $M\ge0$. Let $\Omega\subset\mathbb{R}^d$ be open and convex, and let $u\in C^s(\Omega)$ satisfy $\operatorname{Lip}_\Omega(D^su)\le M$. For $a,x\in\Omega$ and $0\le j\le s$,
\begin{equation}
\label{eq:three-taylor-bound}
 \left\lVertD^ju(x)-D^jJ_a^su(x)\right\rVert_{\mathrm{op}}
 \le \frac{M}{(s+1-j)!}|x-a|^{s+1-j}.
\end{equation}
If a symmetric $j$-linear form $T$, $j\ge1$, satisfies $|T[\xi^j]|\le B$ for every $|\xi|=1$, then
\begin{equation}
\label{eq:three-polarization-bound}
 \left\lVertT\right\rVert_{\mathrm{op}}\le\frac{j^j}{j!}B.
\end{equation}

Put $\eta=x-a$ and $k=s-j$. If $k=0$, \eqref{eq:three-taylor-bound} is the defining Lipschitz bound on $D^su$. If $k\ge1$, applying the fundamental theorem of calculus $k$ times to the tensor-valued map $t\mapsto D^ju(a+t\eta)$ gives
\begin{equation}
\label{eq:three-taylor-integral}
 D^ju(a+\eta)-D^jJ_a^su(a+\eta)
 =\frac1{(k-1)!}\int_0^1(1-t)^{k-1}
 \bigl(D^su(a+t\eta)-D^su(a)\bigr)[\eta^k] \,\mathrm d t.
\end{equation}
For completeness, the iterated integral formula follows inductively from $g(1)-g(0)=\int_0^1g'(t)\,\mathrm d t$: integration over $0<t_k<\cdots<t_1<1$ reduces to integration against $(1-t_k)^{k-1}/(k-1)!$. Subtracting the constant value $D^su(a)$ accounts for the last Taylor term. The norm of the integrand in \eqref{eq:three-taylor-integral} is at most $Mt|\eta|^{k+1}$, and $\int_0^1t(1-t)^{k-1}\,\mathrm d t=1/(k(k+1))$. This proves \eqref{eq:three-taylor-bound}.

For \eqref{eq:three-polarization-bound}, multi-linearity gives
\begin{equation}
\label{eq:three-polarization-identity}
 T[v_1,\ldots,v_j]
 =\frac1{2^jj!}\sum_{\varepsilon\in\{-1,1\}^j}
 \left(\prod_{i=1}^j\varepsilon_i\right)
 T\left[\left(\sum_{i=1}^j\varepsilon_i v_i\right)^j\right].
\end{equation}
Indeed, after expansion, summation in $\varepsilon_i$ kills every term in which $v_i$ occurs an even number of times. Since the total degree is $j$, the surviving terms contain every $v_i$ exactly once; there are $j!$ such terms. For $|v_i|\le1$, each vector in \eqref{eq:three-polarization-identity} has norm at most $j$. The triangle inequality now gives \eqref{eq:three-polarization-bound}.

\label{lem:three-zero-order}
Under \eqref{eq:training_data}, if $s=0$, the defined extension satisfies
\begin{equation}
\label{eq:three-zero-envelope}
 F(x)=\min_{i\in[N]}\{f(X_i)+M|x-X_i|\},\qquad x\in\mathbb{R}^d.
\end{equation}
It is continuous, $F(X_i)=P_i(X_i)$, and $\operatorname{Lip}(F)\le M$.

\label{lem:three-quadratic-envelope}
Fix $d,N\in\mathbb{N}_+$ and $M>0$. Let $X_i,G_i\in\mathbb{R}^d$ and $f_i\in\mathbb{R}$ for $i=1,\ldots,N$, and set $P_i(x)=f_i+G_i\cdot(x-X_i)$. Define
\begin{equation}
\label{eq:three-quadratic-data}
g_i(y)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} P_i(y)+\frac M2|y-X_i|^2+\frac M2|y|^2,\qquad g(y)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\min_i g_i(y),\qquad v_i(x)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} G_i+M(x-X_i).
\end{equation}
Then, for every $x\in\mathbb{R}^d$,
\begin{equation}
\label{eq:three-variance-envelope-identity}
\operatorname{conv}(g)(x)-\frac M2|x|^2=\min_{\lambda\in\Delta_N}\left\{\sum_i\lambda_i\left(P_i(x)+\frac M2|x-X_i|^2\right)-\frac1{4M}\operatorname{Var}_\lambda(v(x))\right\}.
\end{equation}

\label{lem:three-first-order}
Under \eqref{eq:training_data}, if $s=1$, then $F\in C^1(\mathbb{R}^d)$,
\begin{equation}
\label{eq:three-first-order-conclusions}
F(X_i)=P_i(X_i),\qquad \nabla F(X_i)=\nabla P_i(X_i),\qquad |\nabla F(x)-\nabla F(y)|\le M|x-y|
\end{equation}
for $i\in[N]$ and $x,y\in\mathbb{R}^d$.

For $s=1$, one has $\mathcal I_1=\{1\}$, $F=F_1$, $p=2$, $\beta=0$, and $A_s=1/2$. Put $f_i\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} f(X_i)$ and $G_i\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\nabla f(X_i)$; then \eqref{eq:training_data} gives $P_i(x)=f_i+G_i\cdot(x-X_i)$. Let $g_i,g,v_i$ be as in Lemma~\ref{lem:three-quadratic-envelope}, and define $\widetilde F(x)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\operatorname{conv}(g)(x)-M|x|^2/2$ for $x\in\mathbb{R}^d$. By \eqref{eq:entropy-variance-extension__primal} and \eqref{eq:three-variance-envelope-identity},
\[
F(x)=\min_{\lambda\in\Delta_N}\left\{\sum_i\lambda_i\left(P_i(x)+\frac M2|x-X_i|^2\right)-\frac1{4M}\operatorname{Var}_\lambda(v(x))\right\}=\widetilde F(x),\qquad x\notin\mathbb X^N.
\]

Fix $a,b\in\mathbb X^N$, and put $G_a\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\nabla f(a)$, $G_b\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\nabla f(b)$, $\eta\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} b-a$, $\Delta\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} G_b-G_a$, and $z\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}(a+b)/2+\Delta/(2M)$. Applying Lemma~\ref{lem:three-taylor} with $\Omega=\mathbb{R}^d$, $u=f$, $s=1$, and $j=0$ gives
\[
f(b)+G_b\cdot(z-b)-\frac M2|z-b|^2\le f(z)\le f(a)+G_a\cdot(z-a)+\frac M2|z-a|^2.
\]
Since $z-a=\eta/2+\Delta/(2M)$ and $z-b=-\eta/2+\Delta/(2M)$,
\begin{equation}
\label{eq:three-sharp-compatibility}
\begin{aligned}
f(b)-f(a)
&\le G_a\cdot(z-a)-G_b\cdot(z-b)+\frac M2\bigl(|z-a|^2+|z-b|^2\bigr)\\
&=\frac12(G_a+G_b)\cdot\eta-\frac{|\Delta|^2}{2M}+\frac M4|\eta|^2+\frac{|\Delta|^2}{4M}\\
&=\frac12(G_a+G_b)\cdot(b-a)+\frac M4|a-b|^2-\frac1{4M}|G_a-G_b|^2.
\end{aligned}
\end{equation}

Put $b_i\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} G_i-MX_i$, $d_i\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} f_i-G_i\cdot X_i+\frac M2|X_i|^2-\frac{|b_i|^2}{4M}$, and $\bar b(\lambda)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\sum_i\lambda_i b_i$. For $x\in\mathbb{R}^d$ and $\lambda\in\Delta_N$,
\[
\begin{aligned}
P_i(x)+\frac M2|x-X_i|^2&=\frac M2|x|^2+x\cdot b_i+d_i+\frac{|b_i|^2}{4M},\\
\operatorname{Var}_\lambda(v(x))&=\sum_i\lambda_i|b_i+Mx|^2-|\bar b(\lambda)+Mx|^2=\sum_i\lambda_i|b_i|^2-|\bar b(\lambda)|^2.
\end{aligned}
\]
Substitution in \eqref{eq:three-variance-envelope-identity} gives
\begin{equation}
\label{eq:three-first-order-potential}
\begin{aligned}
\widetilde F(x)&=\frac M2|x|^2+\psi(x),\qquad \psi(x)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\min_{\lambda\in\Delta_N}\Phi_x(\lambda),\\
\Phi_x(\lambda)&\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\sum_i\lambda_i d_i+x\cdot\bar b(\lambda)+\frac{|\bar b(\lambda)|^2}{4M}.
\end{aligned}
\end{equation}
Since $\Phi_x$ is continuous and $\Delta_N$ is nonempty and compact, $\Lambda_x\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\operatorname*{argmin}_{\lambda\in\Delta_N}\Phi_x(\lambda)\ne\varnothing$. For $\lambda,\lambda'\in\Lambda_x$,
\[
\psi(x)\le\Phi_x\left(\frac{\lambda+\lambda'}2\right)=\frac{\Phi_x(\lambda)+\Phi_x(\lambda')}2-\frac{|\bar b(\lambda)-\bar b(\lambda')|^2}{16M}=\psi(x)-\frac{|\bar b(\lambda)-\bar b(\lambda')|^2}{16M}.
\]
Thus $\bar b(\lambda)=\bar b(\lambda')$, and $b_x\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\bar b(\lambda)$, $\lambda\in\Lambda_x$, is well defined.

Fix $x,y\in\mathbb{R}^d$ and choose $\lambda_x\in\Lambda_x$, $\lambda_y\in\Lambda_y$. For $t\in(0,1]$, $(1-t)\lambda_x+t\lambda_y\in\Delta_N$ and
\[
\begin{aligned}
0&\le\frac{\Phi_x((1-t)\lambda_x+t\lambda_y)-\Phi_x(\lambda_x)}{t}\\
&=\sum_i(\lambda_{y,i}-\lambda_{x,i})d_i+\left(x+\frac{b_x}{2M}\right)\cdot(b_y-b_x)+\frac{t}{4M}|b_y-b_x|^2.
\end{aligned}
\]
Letting $t\downarrow0$ and interchanging $x,y$ gives
\[
\begin{aligned}
0&\le\sum_i(\lambda_{y,i}-\lambda_{x,i})d_i+\left(x+\frac{b_x}{2M}\right)\cdot(b_y-b_x),\\
0&\le\sum_i(\lambda_{x,i}-\lambda_{y,i})d_i+\left(y+\frac{b_y}{2M}\right)\cdot(b_x-b_y).
\end{aligned}
\]
Adding yields
\begin{equation}
\label{eq:three-first-order-monotonicity}
(x-y)\cdot(b_x-b_y)\le-\frac{|b_x-b_y|^2}{2M}.
\end{equation}
Consequently,
\[
|b_x-b_y|^2\le-2M(x-y)\cdot(b_x-b_y)\le2M|x-y|\,|b_x-b_y|,
\qquad |b_x-b_y|\le2M|x-y|.
\]
Moreover,
\[
\begin{aligned}
\psi(y)&\le\Phi_y(\lambda_x)=\psi(x)+b_x\cdot(y-x),\\
\psi(x)&\le\Phi_x(\lambda_y)=\psi(y)+b_y\cdot(x-y).
\end{aligned}
\]
Hence, for $h\in\mathbb{R}^d$,
\[
-2M|h|^2\le(b_{x+h}-b_x)\cdot h\le\psi(x+h)-\psi(x)-b_x\cdot h\le0.
\]
It follows that $\lim_{h\to0,\ h\ne0}|\psi(x+h)-\psi(x)-b_x\cdot h|/|h|=0$, so $\nabla\psi(x)=b_x$. The Lipschitz estimate for $x\mapsto b_x$ gives $\psi,\widetilde F\in C^1(\mathbb{R}^d)$ and $\nabla\widetilde F(x)=Mx+b_x$. By \eqref{eq:three-first-order-monotonicity},
\begin{equation}
\label{eq:three-first-order-sharp-gradient}
\begin{aligned}
|\nabla\widetilde F(x)-\nabla\widetilde F(y)|^2
&=M^2|x-y|^2+2M(x-y)\cdot(b_x-b_y)+|b_x-b_y|^2\\
&\le M^2|x-y|^2.
\end{aligned}
\end{equation}

Fix $i\in[N]$ and define $\ell_i(z)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} f_i+\frac M2|X_i|^2+(G_i+MX_i)\cdot(z-X_i)$. For $j\in[N]$, put $z_{ij}\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}(X_i+X_j)/2+(G_i-G_j)/(2M)$ and $C_{ij}\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} g_j(z_{ij})-\ell_i(z_{ij})$. Completing the square gives, for $z\in\mathbb{R}^d$,
\begin{equation}
\label{eq:three-first-order-contact}
\begin{aligned}
g_j(z)-\ell_i(z)&=M|z-z_{ij}|^2+C_{ij},\\
\min_{z\in\mathbb{R}^d}(g_j(z)-\ell_i(z))
&=C_{ij}=f_j-f_i+\frac12(G_i+G_j)\cdot(X_i-X_j)\\
&\quad+\frac M4|X_i-X_j|^2-\frac1{4M}|G_i-G_j|^2\ge0,
\end{aligned}
\end{equation}
where the inequality is \eqref{eq:three-sharp-compatibility} with $(a,b)=(X_j,X_i)$. Therefore,
\[
\ell_i\le\operatorname{conv}(g)\le g_i,\qquad
\ell_i(X_i)=g_i(X_i)=f_i+\frac M2|X_i|^2,
\qquad \widetilde F(X_i)=f_i.
\]
Set $\varphi_i\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\operatorname{conv}(g)-\ell_i$. Since $\operatorname{conv}(g)=\widetilde F+M|\cdot|^2/2$, one has $\varphi_i\in C^1(\mathbb{R}^d)$, $\varphi_i\ge0$, and $\varphi_i(X_i)=0$. For every $e\in\mathbb{R}^d$ and both signs,
\[
0\le\lim_{t\downarrow0}\frac{\varphi_i(X_i\pm te)-\varphi_i(X_i)}{t}
=\pm\nabla\varphi_i(X_i)\cdot e.
\]
Thus $\nabla\varphi_i(X_i)=0$ and $\nabla\widetilde F(X_i)=\nabla\ell_i(X_i)-MX_i=G_i$. The site assignment \eqref{eq:entropy-variance-extension__primal___SITES} and the off-site identity give
\begin{equation}
\label{eq:three-first-order-envelope-global}
F(x)=\widetilde F(x)=\operatorname{conv}(g)(x)-\frac M2|x|^2,\qquad x\in\mathbb{R}^d.
\end{equation}
Consequently, $F\in C^1(\mathbb{R}^d)$, $F(X_i)=f_i=P_i(X_i)$, $\nabla F(X_i)=G_i=\nabla P_i(X_i)$, and \eqref{eq:three-first-order-sharp-gradient} yields $|\nabla F(x)-\nabla F(y)|\le M|x-y|$ for all $x,y\in\mathbb{R}^d$.

\label{lem:three-scale}
Under \eqref{eq:training_data} and~\eqref{eq:doubling}, suppose $s\ge2$ and put
\begin{equation}
\label{eq:three-L-definition}
 L_{s,D} \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} \left(\frac43\,2^qD^2\right)^{1/(2s)}.
\end{equation}
Then, for $x\notin \mathbb{X}^N$,
\begin{equation}
\label{eq:three-R-comparison}
 \rho_{\mathbb{X}^N}(x)\le R(x)\le L_{s,D}\rho_{\mathbb{X}^N}(x),
 \qquad
 L_{s,D}^{s+1}\le8\,2^{s+1}D^3.
\end{equation}

Fix $x\notin \mathbb{X}^N$, set $\rho=\rho_{\mathbb{X}^N}(x)$, and choose a site $a$ at distance $\rho$. Write $\mu_0=\mu(B_{\mathbb{X}^N}(a,\rho))>0$. Every point of this ball is at distance less than $2\rho$ from $x$, whence $S_q(x)\ge(2\rho)^{-q}\mu_0$. For $j\ge0$, the sites with $2^j\rho\le r_i(x)<2^{j+1}\rho$ belong to $B_{\mathbb{X}^N}(a,2^{j+2}\rho)$ and have total mass at most $D^{j+2}\mu_0$. Since $q>2s$,
\begin{equation}
\label{eq:three-annulus}
 S_{q-2s}(x)
 \le D^2\mu_0\rho^{2s-q}
 \sum_{j=0}^\infty(D2^{2s-q})^j
 \le\frac43D^2\mu_0\rho^{2s-q}.
\end{equation}
The last step uses $D2^{2s-q}\le1/4$, which follows from \eqref{eq:three-aux-parameters}. Divide \eqref{eq:three-annulus} by the lower bound for $S_q$ and use $R^{2s}=S_{q-2s}/S_q$. The lower bound for $R$ follows from $r_i\ge\rho$ and $\sum_i\theta_i=1$.
Finally, $2^q\le2^{2s+3}D$ and $(s+1)/(2s)\le3/4$. Consequently,
\begin{equation}
\label{eq:three-L-simplification}
 L_{s,D}^{s+1}
 \le2^{s+1}(32/3)^{(s+1)/(2s)}D^{3(s+1)/(2s)}
 \le8\,2^{s+1}D^3,
\end{equation}
since $32/3<16$ and $D\ge1$.

\label{lem:three-entropy}
Fix $N,d\in\mathbb{N}_+$. Let $w_i\in\mathbb{R}$, $b_i\in\mathbb{R}^d$, $\theta_i>0$ with $\sum_i\theta_i=1$, and $c>0$. The function
\begin{equation}
\label{eq:three-abstract-primal}
 \mathcal L(\lambda) \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} \sum_i\lambda_i w_i+c\left|\sum_i\lambda_i b_i\right|^2
 +\operatorname{KL}(\lambda\mid\theta)
\end{equation}
has a unique minimizer $\lambda^*\in\Delta_N$, and every coordinate of $\lambda^*$ is positive. If $z_*=\sum_i\lambda_i^*b_i$, then
\begin{equation}
\label{eq:three-gibbs-dual}
 \begin{aligned}
 \lambda_i^*&=\frac{\theta_i \mathrm{e}^{-w_i-2c z_*\cdot b_i}}
 {\sum_j\theta_j \mathrm{e}^{-w_j-2c z_*\cdot b_j}},\\
 \min_{\lambda\in\Delta_N}\mathcal L(\lambda)
 &=\max_{z\in\mathbb{R}^d}\left\{-c|z|^2-
 \log\sum_i\theta_i \mathrm{e}^{-w_i-2c z\cdot b_i}\right\}.
 \end{aligned}
\end{equation}
The maximizer is unique. These optimizers and the optimal value depend smoothly on any finite-dimensional parameter on which $w_i,b_i,\theta_i$ depend smoothly, while the weights remain positive.

\label{lem:three-normalization}
Under \eqref{eq:training_data} and~\eqref{eq:doubling}, suppose $s\ge2$ and fix $\vartheta\in[0,1]$. Fix a witness $f$, fix $x_0\notin \mathbb{X}^N$, put $\rho=\rho_{\mathbb{X}^N}(x_0)$, and fix the polynomial $Q=J_{x_0}^sf$. In a neighborhood of $x_0$, define
\begin{equation}
\label{eq:three-normalized-data}
 \begin{aligned}
 c&\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\frac{s}{4(s-1)},
 &\delta_i(x)&\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\frac{P_i(x)-Q(x)}{MR(x)^m},\\
 b_i^{(\vartheta)}(x)&\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
 \sqrt{\vartheta}\,\frac{v_i(x)-\nabla Q(x)}{MR(x)^s},
 &w_i^{(\vartheta)}(x)&\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
 \frac{\delta_i(x)}\beta+
 \frac{A_s}\beta\left(\frac{r_i(x)}{R(x)}\right)^{2s}
 -c\left|b_i^{(\vartheta)}(x)\right|^2.
 \end{aligned}
\end{equation}
Let $\mathfrak h_\vartheta(x)$ be the minimum in~\eqref{eq:three-abstract-primal} with costs $w_i^{(\vartheta)}(x)$, vectors $b_i^{(\vartheta)}(x)$, weights $\theta_i(x)$, and the fixed coefficient $c=s/[4(s-1)]$. Then
\begin{equation}
\label{eq:three-F-normalized}
 F_\vartheta(x)=Q(x)+\beta MR(x)^m\mathfrak h_\vartheta(x).
\end{equation}
At $x_0$, abbreviate $u_i=(r_i(x_0)/R(x_0))^s$ and $V_i=1+u_i^2$, and let $\pi_i^{(\vartheta)}$ be the minimizing weights and
\[
 z_{0,\vartheta}\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
 \sum_i\pi_i^{(\vartheta)}b_i^{(\vartheta)}(x_0).
\]
Then
\begin{equation}
\label{eq:three-normalized-bounds}
 \begin{gathered}
 \left|b_i^{(\vartheta)}(x_0)\right|\le u_i,
 \qquad
 \frac{u_i^2}{12}-1\le w_i^{(\vartheta)}(x_0)\le1+u_i^2,
 \qquad
 \sum_i\theta_i(x_0)u_i^2=1,\\
 -1\le\mathfrak h_\vartheta(x_0)\le\frac56,
 \qquad
 |z_{0,\vartheta}|\le3,
 \qquad
 \pi_i^{(\vartheta)}
 \le\mathrm e^{64}\theta_i(x_0)\mathrm e^{-u_i^2/24}.
 \end{gathered}
\end{equation}
With $K_0=\mathrm e^{65}$ and $\kappa=24\mathrm e$, for every integer $k\ge1$,
\begin{equation}
\label{eq:three-moment-bound}
 \sum_i\pi_i^{(\vartheta)}V_i^k\le K_0\kappa^k k!.
\end{equation}
At the endpoint $\vartheta=0$,
\begin{equation}
\label{eq:three-zero-parameter-normalization}
 b_i^{(0)}\equiv0,
 \qquad
 z_{0,0}=0.
\end{equation}
All constants in these conclusions are independent of the fixed parameter $\vartheta\in[0,1]$.

\label{lem:three-majorant-calculus}
Majorization is preserved by addition, bounded bilinear products, and composition with a zero-constant-term majorant. In particular:
\begin{enumerate}
\item If $G\preccurlyeq B$, $H\preccurlyeq C$, and the bilinear multiplication has norm at most one, then $GH\preccurlyeq BC$.
\item If $G$ is scalar valued, $G(0,0)=0$, and $G\preccurlyeq B$ with $B(0,0)=0$, then
\begin{equation}
\label{eq:three-analytic-majorants}
 \mathrm{e}^G-1\preccurlyeq \mathrm{e}^B-1,\quad
 (1+G)^{-1}\preccurlyeq(1-B)^{-1},\quad
 \log(1+G)\preccurlyeq-\log(1-B).
\end{equation}
\item If $G\preccurlyeq B(t,v)$ and $y(0)=0$, $y(t)\preccurlyeq Y(t)$ with $Y(0)=0$, then $G(t,y(t))\preccurlyeq B(t,Y(t))$.
\end{enumerate}
These statements apply to finite jets without an analyticity hypothesis on $G,H,y$.

\label{lem:three-primitives}
Use the setting and notation of Lemma~\ref{lem:three-normalization}, including a fixed $\vartheta\in[0,1]$. Fix a unit vector $\xi\in\mathbb{R}^d$ and substitute $x=x_0+\rho t\xi$, keeping $Q=J_{x_0}^sf$ fixed. Define the nonnegative formal series
\begin{equation}
\label{eq:three-geometric-majorants}
\begin{aligned}
\ell(t)&\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}-\tfrac12\log(1-2t-t^2), &g(t)&\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}-\log\bigl(2-\mathrm e^{q\ell(t)}\bigr),\\
B(t)&\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} g(t)/s, &T(t)&\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} q\ell(t)+g(t),\\
b(t)&\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\frac{(1+t)^s+(1+t)\mathrm e^{(s-1)\ell(t)}}{s!}\,\mathrm e^{sB(t)},\\
a(t)&\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\frac{(1+t)^m}{\beta m!}\mathrm e^{mB(t)}+\frac{A_s}{\beta}\mathrm e^{2s(\ell(t)+B(t))}+c\,b(t)^2.
\end{aligned}
\end{equation}
Then, for every $i\in[N]$, in the sense of Definition~\ref{def:three-majorization},
\begin{equation}
\label{eq:three-primitive-bounds}
\begin{aligned}
\log\frac{R(x_0+\rho t\xi)}{R(x_0)}&\preccurlyeq B(t), &\log\frac{\theta_i(x_0+\rho t\xi)}{\theta_i(x_0)}&\preccurlyeq T(t),\\
b_i^{(\vartheta)}(x_0+\rho t\xi)&\preccurlyeq u_i b(t), &w_i^{(\vartheta)}(x_0+\rho t\xi)&\preccurlyeq V_i a(t).
\end{aligned}
\end{equation}
The scalar functions $b(t)$ and $a(t)$ are majorants and are not the normalized vectors or costs. They are independent of $\vartheta$; in particular, they are not set to zero at $\vartheta=0$. Moreover,
\begin{equation}
\label{eq:three-primitive-constants}
b(0)=2/s!\le1,\qquad a(0)=\frac12+\frac2{\beta m!}+\frac{s}{\beta(s!)^2}\le\frac43.
\end{equation}

Put $x(t)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} x_0+\rho t\xi$, $r_{i0}\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} r_i(x_0)$, and $R_0\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} R(x_0)$. For $i\in[N]$ and $|t|<1$, $r_i(x(t))\ge r_{i0}-\rho|t|\ge\rho(1-|t|)>0$. Set $L_i(t)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\log(r_i(x(t))/r_{i0})$, $\alpha_i\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\rho\langle x_0-X_i,\xi\rangle/r_{i0}^2$, and $\eta_i\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\rho^2/r_{i0}^2$. Then
\begin{equation}
\label{eq:three-distance-log-majorant}
\frac{r_i(x(t))^2}{r_{i0}^2}=1+2\alpha_i t+\eta_i t^2,\qquad |\alpha_i|\le\frac{\rho}{r_{i0}}\le1,\qquad 0<\eta_i\le1.
\end{equation}
Since $2\alpha_i t+\eta_i t^2\preccurlyeq2t+t^2$ and both polynomials vanish at zero, Lemma~\ref{lem:three-majorant-calculus} gives $L_i(t)=\frac12\log(1+2\alpha_i t+\eta_i t^2)\preccurlyeq\ell(t)$, with $L_i(0)=\ell(0)=0$. The formal identities $\ell(t)=\frac12\sum_{k\ge1}(2t+t^2)^k/k$ and $g(t)=\sum_{k\ge1}(\mathrm e^{q\ell(t)}-1)^k/k$ give $\ell,g,B,T\in t\mathbb{R}_{\ge0}[[t]]$ and $a,b\in\mathbb{R}_{\ge0}[[t]]$.

For $\gamma\in[0,q]$, put $\omega_{i,\gamma}\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\mu_i r_{i0}^{-\gamma}/S_\gamma(x_0)>0$ and $G_\gamma(t)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} S_\gamma(x(t))/S_\gamma(x_0)-1$. Since $\sum_{i=1}^N\omega_{i,\gamma}=1$, one has $G_\gamma(0)=0$ and, by~\eqref{eq:three-analytic-majorants},
\[
G_\gamma(t)=\sum_{i=1}^N\omega_{i,\gamma}\bigl(\mathrm e^{-\gamma L_i(t)}-1\bigr)\preccurlyeq\sum_{i=1}^N\omega_{i,\gamma}\bigl(\mathrm e^{\gamma\ell(t)}-1\bigr)=\mathrm e^{\gamma\ell(t)}-1.
\]
The majorant on the right has zero constant coefficient, and
\[
\mathrm e^{\gamma\ell}-1=\sum_{j\ge1}\frac{\gamma^j\ell^j}{j!}\preccurlyeq\sum_{j\ge1}\frac{q^j\ell^j}{j!}=\mathrm e^{q\ell}-1.
\]
A second application of~\eqref{eq:three-analytic-majorants} yields
\begin{equation}
\label{eq:three-sum-log-majorant}
\begin{aligned}
\log\frac{S_\gamma(x(t))}{S_\gamma(x_0)}
&=\log(1+G_\gamma(t))\preccurlyeq-\log\bigl(2-\mathrm e^{\gamma\ell(t)}\bigr)\\
&=\sum_{k\ge1}\frac{(\mathrm e^{\gamma\ell(t)}-1)^k}{k}\preccurlyeq\sum_{k\ge1}\frac{(\mathrm e^{q\ell(t)}-1)^k}{k}=g(t).
\end{aligned}
\end{equation}
Define $\Lambda(t)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\log(R(x(t))/R_0)$. Since $q-2s\in[0,q]$, $R^{2s}=S_{q-2s}/S_q$, and $\theta_i=\mu_i r_i^{-q}/S_q$, equation~\eqref{eq:three-sum-log-majorant} gives
\[
\begin{aligned}
\Lambda(t)&=\frac1{2s}\left(\log\frac{S_{q-2s}(x(t))}{S_{q-2s}(x_0)}-\log\frac{S_q(x(t))}{S_q(x_0)}\right)\preccurlyeq\frac{g(t)+g(t)}{2s}=B(t),\\
\log\frac{\theta_i(x(t))}{\theta_i(x_0)}&=-qL_i(t)-\log\frac{S_q(x(t))}{S_q(x_0)}\preccurlyeq q\ell(t)+g(t)=T(t).
\end{aligned}
\]
In particular, $\Lambda(0)=B(0)=0$, and for every $\sigma\ge0$, $\mathrm e^{-\sigma\Lambda}\preccurlyeq\mathrm e^{\sigma B}$ and $\mathrm e^{\sigma L_i}\preccurlyeq\mathrm e^{\sigma\ell}$.

By~\eqref{eq:training_data}, $P_i=J_{X_i}^sf$ and $D^jQ(x_0)=D^jf(x_0)$ for $0\le j\le s$. Lemma~\ref{lem:three-taylor}, applied with base point $X_i$ and evaluation point $x_0$, therefore gives
\begin{equation}
\label{eq:three-polynomial-coefficients}
\left\lVertD^j(P_i-Q)(x_0)\right\rVert_{\mathrm{op}}=\left\lVertD^jJ_{X_i}^sf(x_0)-D^jf(x_0)\right\rVert_{\mathrm{op}}\le\frac{Mr_{i0}^{m-j}}{(m-j)!},\qquad 0\le j\le s.
\end{equation}
Since $\rho\le r_{i0}$ and $|\xi|=1$, equation~\eqref{eq:three-polynomial-coefficients} implies
\[
\begin{aligned}
\bigl|[t^j](P_i-Q)(x(t))\bigr|&=\frac{\rho^j}{j!}\bigl|D^j(P_i-Q)(x_0)[\xi^j]\bigr|\le\frac{Mr_{i0}^m}{j!(m-j)!},&&0\le j\le s,\\
\bigl|[t^j]\nabla(P_i-Q)(x(t))\bigr|&=\frac{\rho^j}{j!}\sup_{|h|\le1}\bigl|D^{j+1}(P_i-Q)(x_0)[\xi^j,h]\bigr|\\
&\le\frac{Mr_{i0}^s}{j!(s-j)!},&&0\le j\le s-1.
\end{aligned}
\]
As $\deg(P_i-Q)\le s=m-1$ and $\deg\nabla(P_i-Q)\le s-1$, the remaining coefficients vanish. Thus
\[
\begin{aligned}
(P_i-Q)(x(t))&\preccurlyeq Mr_{i0}^m\sum_{j=0}^s\frac{t^j}{j!(m-j)!}\preccurlyeq\frac{Mr_{i0}^m}{m!}(1+t)^m,\\
\nabla(P_i-Q)(x(t))&\preccurlyeq Mr_{i0}^s\sum_{j=0}^{s-1}\frac{t^j}{j!(s-j)!}\preccurlyeq\frac{Mr_{i0}^s}{s!}(1+t)^s.
\end{aligned}
\]

Set $t_i\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} r_{i0}/R_0$, so $u_i=t_i^s$ and $V_i=1+t_i^{2s}$. Since $x(t)-X_i\preccurlyeq r_{i0}+\rho t\preccurlyeq r_{i0}(1+t)$, the identity $v_i(x)=\nabla P_i(x)+(M/s!)r_i(x)^{s-1}(x-X_i)$ and~\eqref{eq:three-normalized-data} give
\begin{equation}
\label{eq:three-parameter-vector-majorant}
\begin{aligned}
b_i^{(\vartheta)}(x(t))&=\sqrt\vartheta\,b_i^{(1)}(x(t))\\
&=\frac{\sqrt\vartheta\,\mathrm e^{-s\Lambda(t)}}{MR_0^s}\left(\nabla(P_i-Q)(x(t))+\frac{M r_{i0}^{s-1}}{s!}\mathrm e^{(s-1)L_i(t)}(x(t)-X_i)\right)\\
&\preccurlyeq\sqrt\vartheta\,\frac{t_i^s}{s!}\bigl((1+t)^s+(1+t)\mathrm e^{(s-1)\ell(t)}\bigr)\mathrm e^{sB(t)}\\
&=\sqrt\vartheta\,u_i b(t)\preccurlyeq u_i b(t).
\end{aligned}
\end{equation}
For the quadratic contribution, the bilinear-product assertion of Lemma~\ref{lem:three-majorant-calculus}, with $|\langle u,v\rangle|\le|u|\,|v|$, gives
\[
c|b_i^{(\vartheta)}(x(t))|^2=c\langle b_i^{(\vartheta)}(x(t)),b_i^{(\vartheta)}(x(t))\rangle\preccurlyeq\vartheta c u_i^2b(t)^2\preccurlyeq c u_i^2b(t)^2.
\]
Since $m=s+1\le2s$, one has $t_i^m\le1$ for $0<t_i\le1$ and $t_i^m\le t_i^{2s}$ for $t_i\ge1$; hence $t_i^m\le V_i$ and $u_i^2\le V_i$. Using the signed cost in~\eqref{eq:three-normalized-data} and coefficientwise addition, we obtain
\[
\begin{aligned}
w_i^{(\vartheta)}(x(t))&=\frac{(P_i-Q)(x(t))}{\beta MR_0^m}\mathrm e^{-m\Lambda(t)}+\frac{A_s}{\beta}t_i^{2s}\mathrm e^{2s(L_i(t)-\Lambda(t))}-c|b_i^{(\vartheta)}(x(t))|^2\\
&\preccurlyeq\frac{t_i^m}{\beta m!}(1+t)^m\mathrm e^{mB(t)}+\frac{A_s}{\beta}u_i^2\mathrm e^{2s(\ell(t)+B(t))}+c u_i^2b(t)^2\\
&\preccurlyeq V_i a(t).
\end{aligned}
\]
Finally, $\ell(0)=g(0)=B(0)=0$, $A_s=1/m!+\beta/2$, and $c=s/(4\beta)$ give $b(0)=2/s!\le1$ and
\[
a(0)=\frac1{\beta m!}+\frac{A_s}{\beta}+\frac{4c}{(s!)^2}=\frac12+\frac2{\beta m!}+\frac{s}{\beta(s!)^2}\le\frac12+\frac13+\frac12=\frac43,
\]
where $\beta\ge1$, $m!\ge6$, $s!\ge2$, and $s\le2\beta$.

\label{lem:three-gibbs-majorants}
In Lemma~\ref{lem:three-primitives}, let $z_{0,\vartheta}$ and $\pi_i^{(\vartheta)}$ be as in Lemma~\ref{lem:three-normalization}. Define, with $K_0=\mathrm e^{65}$ and $\kappa=24\mathrm e$,
\begin{equation}
\label{eq:three-gibbs-majorants}
 \begin{aligned}
 \alpha(t)&\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} T(t)+a(t)-a(0)+6c\bigl(b(t)-b(0)\bigr),\\
 X(t,v)&\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\alpha(t)+2cb(t)v,\\
 Q_*(t,v)&\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\frac{K_0\kappa X(t,v)}{1-\kappa X(t,v)},\\
 N_*(t,v)&\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} K_0\kappa\bigl(b(t)-b(0)\bigr)
 +K_0\kappa b(t)\left((1-\kappa X(t,v))^{-2}-1\right),\\
 J_*(t,v)&\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\frac{N_*(t,v)+3Q_*(t,v)}{1-Q_*(t,v)},\\
 \mathcal R(t,v)&\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} J_*(t,v)-[v]J_*(0,v)\,v.
 \end{aligned}
\end{equation}
All coefficients in these series are nonnegative, and their constant terms vanish. In particular $\partial_v\mathcal R(0,0)=0$.
Let
\[
 \mathcal K_\vartheta(t,z)
 \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} z-\sum_i\lambda_i^{(\vartheta)}(t,z)
 b_i^{(\vartheta)}(x_0+\rho t\xi)
\]
be the stationarity map, where $\lambda^{(\vartheta)}(t,z)$ is the Gibbs vector in~\eqref{eq:three-gibbs-dual} for the costs $w_i^{(\vartheta)}(x_0+\rho t\xi)$, vectors $b_i^{(\vartheta)}(x_0+\rho t\xi)$, and weights $\theta_i(x_0+\rho t\xi)$. Put
$J_\vartheta=D_z\mathcal K_\vartheta(0,z_{0,\vartheta})$. Then
\begin{equation}
\label{eq:three-stationarity-remainder}
 \left\lVertJ_\vartheta^{-1}\right\rVert_{\mathrm{op}}\le1,
 \qquad
 \mathcal K_\vartheta(t,z_{0,\vartheta}+y)-J_\vartheta y
 \preccurlyeq\mathcal R(t,v).
\end{equation}
If $W(t)=\sum_{n\ge1}W_nt^n$ is the unique formal solution with zero constant term of
\begin{equation}
\label{eq:three-majorant-equation}
 W(t)=\mathcal R(t,W(t)),
\end{equation}
then
\[
 z_\vartheta(x_0+\rho t\xi)-z_{0,\vartheta}\preccurlyeq W(t),
\]
where $z_\vartheta(x)$ denotes the Gibbs mean at the optimizer. Moreover,
\begin{equation}
\label{eq:three-h-majorant}
 \begin{aligned}
 \mathfrak h_\vartheta(x_0+\rho t\xi)-\mathfrak h_\vartheta(x_0)
 &\preccurlyeq
 c\bigl(6W(t)+W(t)^2\bigr)
 -\log(1-Q_*(t,W(t))),\\
 \frac{F_\vartheta(x_0+\rho t\xi)-Q(x_0+\rho t\xi)}
 {\beta MR(x_0)^m}
 &\preccurlyeq\mathcal H(t),\\
 \mathcal H(t)&\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
 \mathrm e^{mB(t)}
 \left[1+c(6W(t)+W(t)^2)-\log(1-Q_*(t,W(t)))\right].
 \end{aligned}
\end{equation}
At $\vartheta=0$ one has, identically in $(t,z)$,
\begin{equation}
\label{eq:three-zero-parameter-stationarity}
 \mathcal K_0(t,z)=z,
 \qquad
 J_0=I,
 \qquad
 \left\lVertJ_0^{-1}\right\rVert_{\mathrm{op}}=1.
\end{equation}
All displayed majorants are uniform in the fixed parameter $\vartheta\in[0,1]$.

\label{lem:three-majorant-radius}
For every integer $s\ge2$ and real $q\ge2s+2$, the series in Lemmas~\ref{lem:three-primitives} and \ref{lem:three-gibbs-majorants} satisfy
\begin{equation}
\label{eq:three-J-geometric-bound}
 J_*(t,v)\preccurlyeq\frac{C_0(qt+v)}{1-C_0(qt+v)},
 \qquad C_0 \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}  \mathrm{e}^{100}.
\end{equation}
The solution $W$ of \eqref{eq:three-majorant-equation} has nonnegative coefficients and satisfies
\begin{equation}
\label{eq:three-radius-bound}
 \tau \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} \frac1{64C_0^3q},\qquad
 r_* \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} \frac1{16C_0^2},\qquad
 W(\tau)\le r_*,\qquad \mathcal H(\tau)\le8.
\end{equation}
In particular, $[t^n]\mathcal H(t)\le8\tau^{-n}$ for every $n\in\mathbb N$. Since the scalar series in Lemmas~\ref{lem:three-primitives} and~\ref{lem:three-gibbs-majorants} are unchanged, every conclusion here holds uniformly for each fixed $\vartheta\in[0,1]$.

Put $\varepsilon\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} C_0^{-1}=\mathrm e^{-100}$, $t_0\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\varepsilon/q$, and $v_0\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\varepsilon$. Recall $m=s+1$, $\beta=s-1$, $c=s/(4\beta)\le1/2$, $K_0=\mathrm e^{65}$, and $\kappa=24\mathrm e$. The series in~\eqref{eq:three-geometric-majorants} and~\eqref{eq:three-gibbs-majorants} have nonnegative coefficients. Numerical evaluations of such series are understood as increasing limits of finite partial sums. Since $n!\ge2^{n-1}$ for $n\ge1$, with strict inequality for $n\ge3$,
\[
\frac83=1+1+\frac1{2!}+\frac1{3!}<\mathrm e=\sum_{n=0}^{\infty}\frac1{n!}<1+\sum_{n=1}^{\infty}2^{1-n}=3.
\]
In particular, $0<\varepsilon<2^{-100}$, $q\ge6$, $s/q\le1/2$, and $m/q\le1/2$. For $0\le y\le1/2$,
\begin{equation}
\label{eq:three-elementary-series-bounds}
\begin{aligned}
-\log(1-y)&=\sum_{n\ge1}\frac{y^n}{n}\le\sum_{n\ge1}y^n=\frac{y}{1-y}\le2y,\\
\mathrm e^y-1&=\sum_{n\ge1}\frac{y^n}{n!}\le\sum_{n\ge1}y^n=\frac{y}{1-y}\le2y.
\end{aligned}
\end{equation}
For $0\le t\le1/8$, $2t+t^2\le17/64$ and $2t+t^2\le(17/8)t$, so
\[
\ell(t)=\frac12\sum_{n\ge1}\frac{(2t+t^2)^n}{n}\le\frac{2t+t^2}{2(1-2t-t^2)}\le\frac{68}{47}t\le2t.
\]
Since $t_0<1/8$, equations~\eqref{eq:three-geometric-majorants} and~\eqref{eq:three-elementary-series-bounds} give
\begin{equation}
\label{eq:three-small-primitive-values}
\begin{aligned}
q\ell(t_0)&\le2\varepsilon,&\mathrm e^{q\ell(t_0)}-1&\le4\varepsilon,\\
2-\mathrm e^{q\ell(t_0)}&\ge1-4\varepsilon>\frac12,&g(t_0)&\le2\bigl(\mathrm e^{q\ell(t_0)}-1\bigr)\le8\varepsilon,\\
T(t_0)&=q\ell(t_0)+g(t_0)\le10\varepsilon,&sB(t_0)&=g(t_0)\le8\varepsilon,\\
mB(t_0)&=\frac ms g(t_0)\le12\varepsilon.&&
\end{aligned}
\end{equation}
Here $m/s\le3/2$, and the bound $\mathrm e^{q\ell(t_0)}-1<1$ gives convergence of the defining logarithmic series for $g(t_0)$.

The inequalities $\log(1+t_0)\le t_0$, $s/q\le1/2$, and $(2s-1)/q\le1$ imply
\[
\begin{aligned}
(1+t_0)^s&\le\mathrm e^{st_0}\le\mathrm e^{\varepsilon/2},\\
(1+t_0)\mathrm e^{(s-1)\ell(t_0)}&\le\mathrm e^{t_0+2(s-1)t_0}=\mathrm e^{(2s-1)\varepsilon/q}\le\mathrm e^\varepsilon.
\end{aligned}
\]
Thus, using $b(0)=2/s!\le1$ and~\eqref{eq:three-elementary-series-bounds},
\begin{equation}
\label{eq:three-b-small-value}
\begin{aligned}
b(t_0)&\le\frac{2}{s!}\mathrm e^{9\varepsilon}=b(0)\mathrm e^{9\varepsilon}\le1+18\varepsilon\le2,\\
0\le b(t_0)-b(0)&\le b(0)(\mathrm e^{9\varepsilon}-1)\le18\varepsilon.
\end{aligned}
\end{equation}
For the three terms defining $a$, the respective factors satisfy
\[
\begin{aligned}
m\log(1+t_0)+mB(t_0)&\le\frac m q\varepsilon+12\varepsilon\le13\varepsilon,\\
2s\bigl(\ell(t_0)+B(t_0)\bigr)&\le\frac{4s}{q}\varepsilon+16\varepsilon\le18\varepsilon,\\
b(t_0)^2&\le b(0)^2\mathrm e^{18\varepsilon}.
\end{aligned}
\]
Consequently, by~\eqref{eq:three-primitive-constants} and $18\varepsilon<1/2$,
\begin{equation}
\label{eq:three-a-small-value}
\begin{aligned}
a(t_0)&\le\left(\frac1{\beta m!}+\frac{A_s}{\beta}+cb(0)^2\right)\mathrm e^{18\varepsilon}=a(0)\mathrm e^{18\varepsilon},\\
0\le a(t_0)-a(0)&\le\frac43(\mathrm e^{18\varepsilon}-1)\le48\varepsilon.
\end{aligned}
\end{equation}
Substitution in~\eqref{eq:three-gibbs-majorants}, with $6c\le3$ and $2c\le1$, gives
\begin{equation}
\label{eq:three-X-small-value}
\begin{aligned}
\alpha(t_0)&\le10\varepsilon+48\varepsilon+3\cdot18\varepsilon=112\varepsilon,\\
X(t_0,v_0)&=\alpha(t_0)+2cb(t_0)v_0\le112\varepsilon+2\varepsilon=114\varepsilon\le128\varepsilon.
\end{aligned}
\end{equation}
Set $Y\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\kappa X(t_0,v_0)$. Then $0\le Y\le72\cdot128\varepsilon=9216\varepsilon<1/4$, so $1-Y>3/4$. Since $18432<(8/3)^{15}<\mathrm e^{15}$,
\begin{equation}
\label{eq:three-Q-small-value}
\begin{aligned}
Q_*(t_0,v_0)&=K_0\sum_{n\ge1}Y^n=\frac{K_0Y}{1-Y}\le2K_0Y\\
&\le18432\mathrm e^{65}\varepsilon\le\mathrm e^{80}\varepsilon=\mathrm e^{-20}<\frac12.
\end{aligned}
\end{equation}
For $0\le Y\le1/4$, $\sum_{n\ge1}(n+1)Y^n=(1-Y)^{-2}-1=Y(2-Y)/(1-Y)^2\le(32/9)Y\le4Y$. Hence, using $5{,}309{,}712<(8/3)^{20}<\mathrm e^{20}$,
\begin{equation}
\label{eq:three-N-small-value}
\begin{aligned}
N_*(t_0,v_0)&=K_0\kappa\bigl(b(t_0)-b(0)\bigr)+K_0\kappa b(t_0)\sum_{n\ge1}(n+1)Y^n\\
&\le\mathrm e^{65}\bigl(72\cdot18+72\cdot2\cdot4\cdot9216\bigr)\varepsilon\\
&=5{,}309{,}712\mathrm e^{65}\varepsilon\le\mathrm e^{85}\varepsilon.
\end{aligned}
\end{equation}
In particular, $1-Q_*(t_0,v_0)\ge1-\mathrm e^{-20}>1/2$. Since $3<\mathrm e^5$ and $4<\mathrm e^2$, equations~\eqref{eq:three-Q-small-value}--\eqref{eq:three-N-small-value} yield
\begin{equation}
\label{eq:three-J-small-value}
\begin{aligned}
J_*(t_0,v_0)=\bigl(N_*(t_0,v_0)+3Q_*(t_0,v_0)\bigr)\sum_{n\ge0}Q_*(t_0,v_0)^n
\le2\bigl(\mathrm e^{85}+3\mathrm e^{80}\bigr)\varepsilon\le4\mathrm e^{85}\varepsilon<\mathrm e^{87}\varepsilon=\mathrm e^{-13}<1.
\end{aligned}
\end{equation}
Write $J_*(t,v)=\sum_{j,k\ge0}c_{jk}t^jv^k$, where $c_{jk}\ge0$ and $c_{00}=0$. For $j+k\ge1$, equation~\eqref{eq:three-J-small-value} gives
\[
\begin{aligned}
0\le c_{jk}t_0^jv_0^k&\le\sum_{a,b\ge0}c_{ab}t_0^av_0^b=J_*(t_0,v_0)<1,\\
c_{jk}&\le t_0^{-j}v_0^{-k}=C_0^{j+k}q^j\le C_0^{j+k}\binom{j+k}{j}q^j\\
&=[t^jv^k]\sum_{n\ge1}C_0^n(qt+v)^n=[t^jv^k]\frac{C_0(qt+v)}{1-C_0(qt+v)}.
\end{aligned}
\]
This proves~\eqref{eq:three-J-geometric-bound}, including its zero constant coefficient. Write $\mathcal R(t,v)=\sum_{a,b\ge0}r_{ab}t^av^b$. By~\eqref{eq:three-gibbs-majorants}, $r_{01}=0$ and $r_{ab}=c_{ab}$ for $(a,b)\ne(0,1)$. Deleting the coefficient of $v$ on both sides of~\eqref{eq:three-J-geometric-bound} therefore gives
\begin{equation}
\label{eq:three-R-scalar-majorant}
\mathcal R(t,v)\preccurlyeq C_0qt+\sum_{n\ge2}C_0^n(qt+v)^n=C_0qt+\frac{C_0^2(qt+v)^2}{1-C_0(qt+v)}.
\end{equation}
For $\tau$ and $r_*$ in~\eqref{eq:three-radius-bound},
\[
q\tau+r_*\le\frac5{64C_0^2},\qquad C_0(q\tau+r_*)\le\frac5{64C_0}\le\frac5{64},\qquad 1-C_0(q\tau+r_*)\ge\frac{59}{64}.
\]
The convergent geometric series in~\eqref{eq:three-R-scalar-majorant} consequently yields
\begin{equation}
\label{eq:three-majorant-invariance}
\mathcal R(\tau,r_*)\le\frac1{64C_0^2}+\frac{25}{3776C_0^2}=\frac{21}{59}r_*<r_*.
\end{equation}

Define $W^{(0)}(t)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}0$ and $W^{(n+1)}(t)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\mathcal R(t,W^{(n)}(t))$ for $n\ge0$. For $U,V\in t\mathbb{R}_{\ge0}[[t]]$, $U\preccurlyeq V$ implies $U^b\preccurlyeq V^b$ for every $b\ge0$, and hence $\mathcal R(t,U)\preccurlyeq\mathcal R(t,V)$ because $r_{ab}\ge0$. Since $r_{00}=0$ and $0=W^{(0)}\preccurlyeq\mathcal R(t,0)=W^{(1)}$, induction gives $W^{(n)}\in t\mathbb{R}_{\ge0}[[t]]$ and $0\preccurlyeq W^{(n)}\preccurlyeq W^{(n+1)}$. For $U,V\in t\mathbb{R}[[t]]$,
\[
\mathcal R(t,U)-\mathcal R(t,V)=(U-V)\sum_{\substack{a\ge0\\b\ge1}}r_{ab}t^a\sum_{\ell=0}^{b-1}U^\ell V^{b-1-\ell}.
\]
Every summand in the last factor belongs to $t^{a+b-1}\mathbb{R}[[t]]$. For each $k\ge0$, only the finitely many pairs $(a,b)$ with $a+b\le k+1$ can contribute to its coefficient of $t^k$. The factor is therefore a well-defined formal series, and $r_{01}=0$ gives its membership in $t\mathbb{R}[[t]]$. Consequently, for every $j\ge1$,
$
U-V\in t^j\mathbb{R}[[t]]$ implies that $\mathcal R(t,U)-\mathcal R(t,V)\in t^{j+1}\mathbb{R}[[t]]$.  
Starting from $W^{(1)}-W^{(0)}=\mathcal R(t,0)\in t\mathbb{R}[[t]]$, induction yields
\[
W^{(n+1)}-W^{(n)}\in t^{n+1}\mathbb{R}[[t]],\qquad [t^j]W^{(n)}=[t^j]W^{(j)}\quad(n\ge j\ge1).
\]
Put $W_j\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}[t^j]W^{(j)}\ge0$. The same order estimate gives
\[
W_j=[t^j]\mathcal R(t,W^{(j-1)}(t))=[t^j]\mathcal R\left(t,\sum_{k=1}^{j-1}W_kt^k\right),\qquad j\ge1.
\]
These are the coefficients of the unique formal solution $W$ by~\eqref{eq:three-W-recursion}.
Let $U(t)=\sum_{j\ge1}u_jt^j$ have $u_j\ge0$ and $U(\tau)\le r_*$. Rearrangement of nonnegative sums gives
\[
\begin{aligned}
\sum_{n\ge0}\tau^n[t^n]\mathcal R(t,U(t))&=\sum_{a,b\ge0}r_{ab}\tau^a\left(\sum_{j\ge1}u_j\tau^j\right)^b\\
&=\mathcal R(\tau,U(\tau))\le\mathcal R(\tau,r_*)<r_*.
\end{aligned}
\]
In particular, the composed series converges at $\tau$. Applying this identity inductively from $W^{(0)}(\tau)=0$ yields $W^{(n)}(\tau)\le r_*$ for every $n\ge0$. For every $L\ge1$, stabilization therefore gives
\[
0\le\sum_{j=1}^{L}W_j\tau^j=\sum_{j=1}^{L}\bigl([t^j]W^{(L)}(t)\bigr)\tau^j\le W^{(L)}(\tau)\le r_*.
\]
Taking the increasing limit in $L$ proves $W(\tau)=\sum_{j\ge1}W_j\tau^j\le r_*$.

Since $\tau/t_0=1/(64C_0^2)\le1$ and $r_*/v_0=1/(16C_0)\le1$, nonnegativity of coefficients and~\eqref{eq:three-small-primitive-values}--\eqref{eq:three-Q-small-value} imply
$
mB(\tau)\le mB(t_0)\le12\varepsilon$ and $Q_*(\tau,W(\tau))\le Q_*(t_0,v_0)\le\mathrm e^{-20}<\frac12$.  
The same nonnegative-sum identity and $Q_*(0,W(0))=Q_*(0,0)=0$ give
\[
\begin{aligned}
\sum_{n\ge0}\tau^n[t^n]\sum_{k\ge1}\frac{Q_*(t,W(t))^k}{k}&=\sum_{k\ge1}\frac{Q_*(\tau,W(\tau))^k}{k}=-\log(1-Q_*(\tau,W(\tau)))<\infty.
\end{aligned}
\]
Equation~\eqref{eq:three-h-majorant}, together with $c\le1/2$, now gives
\begin{equation}
\label{eq:three-H-small-value}
\begin{aligned}
\mathcal H(\tau)&\le\mathrm e^{12\varepsilon}\left[1+\frac12(6r_*+r_*^2)-\log(1-\mathrm e^{-20})\right]\\
&\le2\left(1+\frac{97}{512}+2\mathrm e^{-20}\right)<2\left(1+\frac{97}{512}+\frac12\right)<4<8.
\end{aligned}
\end{equation}
Here $r_*=(16C_0^2)^{-1}\le1/16$ and $\frac12(6/16+1/16^2)=97/512$, while~\eqref{eq:three-elementary-series-bounds} gives $\mathrm e^{12\varepsilon}\le1+24\varepsilon\le2$ and $-\log(1-\mathrm e^{-20})\le2\mathrm e^{-20}<1/2$. Finally, writing $\mathcal H_n\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}[t^n]\mathcal H(t)\ge0$,
\[
0\le\mathcal H_n\tau^n\le\sum_{k\ge0}\mathcal H_k\tau^k=\mathcal H(\tau)<8,\qquad\mathcal H_n\le8\tau^{-n}\quad(n\ge0)
\]
which completes the proof.

\label{lem:three-local-errors}
Under \eqref{eq:training_data} and~\eqref{eq:doubling}, suppose $s\ge2$ and fix $\vartheta\in[0,1]$. Set
\begin{equation}
\label{eq:three-constant-D}
 C_s(D)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} D^3\left[\mathrm e^{2000}(s+1)
 \bigl(2s+\lceil\log_2D\rceil+2\bigr)\right]^{s+1}.
\end{equation}
Then $F_\vartheta\in C^\infty(\mathbb{R}^d\setminus\mathbb X^N)$ and, for $x\notin\mathbb X^N$ and $0\le j\le s$,
\begin{equation}
\label{eq:three-local-errors}
 \|D^jF_\vartheta(x)-D^jf(x)\|_{\mathrm{op}}
 \le C_s(D)M\rho_{\mathbb X^N}(x)^{s+1-j}.
\end{equation}
The constant is uniform in the fixed parameter $\vartheta\in[0,1]$. In particular, at $D=2^{46d}$,
\begin{equation}
\label{eq:three-constant-ds}
 C_s(2^{46d})=2^{138d}
 \left[\mathrm e^{2000}(s+1)(2s+46d+2)\right]^{s+1}.
\end{equation}

Fix $x_0\notin\mathbb X^N$ and the polynomial $Q=J_{x_0}^sf$. The positive distances, finite sums, quotients, and positive real powers defining $R$, $\theta$, and $v$ are smooth off the sites. In a neighborhood of $x_0$, Lemma~\ref{lem:three-normalization} gives the normalized identity for $F_\vartheta$ with this fixed $Q$. The coefficient $c=s/(4(s-1))$ is positive for every parameter value and every $\theta_i$ is positive, so Lemma~\ref{lem:three-entropy} gives a smooth optimal value in that identity. Hence $F_\vartheta$ is smooth near $x_0$; arbitrariness of $x_0$ proves off-site smoothness, including at $\vartheta=0$.

Let $\rho=\rho_{\mathbb X^N}(x_0)>0$ and keep $Q=J_{x_0}^sf$ fixed. For every unit vector $\xi$, Lemmas~\ref{lem:three-gibbs-majorants} and~\ref{lem:three-majorant-radius} give, for $0\le j\le s$,
\begin{equation}
\label{eq:three-directional-estimates}
 |D^j(F_\vartheta-Q)(x_0)[\xi^j]|
 \le8\beta MR(x_0)^m j!
 \left(\frac{64\mathrm e^{300}q}{\rho}\right)^j.
\end{equation}
At $j=0$ the left side means the value. Indeed, the coefficient of $t^j$ in
$F_\vartheta(x_0+\rho t\xi)-Q(x_0+\rho t\xi)$ is
$\rho^jD^j(F_\vartheta-Q)(x_0)[\xi^j]/j!$, and the majorant coefficient is at most $8\tau^{-j}$, with $\tau^{-1}=64\mathrm e^{300}q$.
For $j\ge1$ apply the polarization part of Lemma~\ref{lem:three-taylor}; for $j=0$ no polarization is needed. Lemma~\ref{lem:three-scale} then gives, with $0^0=1$ only for the displayed zero-order factor,
\begin{equation}
\label{eq:three-tensor-estimates}
 \|D^j(F_\vartheta-Q)(x_0)\|_{\mathrm{op}}
 \le8\beta L_{s,D}^m j^j(64\mathrm e^{300}q)^j
 M\rho^{m-j},
 \qquad 0\le j\le s.
\end{equation}
Since $j^j\le m^m$ and $64\mathrm e^{300}q>1$, the constants in this finite range are bounded by
\begin{equation}
\label{eq:three-intermediate-constant}
 \begin{aligned}
 8\beta L_{s,D}^m(64\mathrm e^{300}qm)^m
 &\le64\beta D^3(128\mathrm e^{300}qm)^m\\
 &\le D^3(\mathrm e^{315}qm)^m
 \le D^3(\mathrm e^{2000}qm)^m=C_s(D).
 \end{aligned}
\end{equation}
The first inequality uses $L_{s,D}^m\le8\,2^mD^3$ from Lemma~\ref{lem:three-scale}. For the second, $128<\mathrm e^5$ and $64\beta\le\mathrm e^{10m}$: here $\beta=m-2<m$, $64<\mathrm e^5$, and $m\le\mathrm e^m$, so $64\beta<\mathrm e^{m+5}\le\mathrm e^{10m}$ for $m\ge3$. Finally $D^jQ(x_0)=D^jf(x_0)$ for $j\le s$, so~\eqref{eq:three-tensor-estimates} proves~\eqref{eq:three-local-errors}. Since $d$ is a positive integer, $\log_2(2^{46d})=46d$ is integral, and substitution gives~\eqref{eq:three-constant-ds}. The distance comparison cancels the same positive local mass, and the moment and majorant bounds contain no factor involving $\vartheta$, $N$, the minimum atomic weight, or the sites' separation; thus neither does the stated constant.

\label{lem:three-site-gluing}
Let $s\ge1$, $u\in C^s(\mathbb{R}^d)$, and $G:\mathbb{R}^d\to\mathbb{R}$ satisfy $G(X_i)=u(X_i)$ for $i\in[N]$ and $G\in C^s(\mathbb{R}^d\setminus\mathbb{X}^N)$. Suppose that a finite number $B\ge0$ satisfies
\begin{equation}
\label{eq:three-gluing-hypothesis}
 \|D^jG(x)-D^ju(x)\|_{\mathrm{op}}
 \le B\rho_{\mathbb{X}^N}(x)^{s+1-j},
 \qquad x\notin\mathbb{X}^N,\quad 0\le j\le s.
\end{equation}
Then $G\in C^s(\mathbb{R}^d)$ and $D^jG(X_i)=D^ju(X_i)$ for $i\in[N]$ and $0\le j\le s$.

For $0\le j\le s$, define a scalar field at $j=0$ and a symmetric tensor field at $j\ge1$ by
\begin{equation}
\label{eq:three-extended-error}
 H_j(x) \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} 
 \begin{cases}
 D^jG(x)-D^ju(x),&x\notin\mathbb{X}^N,\\
 0,&x\in\mathbb{X}^N.
 \end{cases}
\end{equation}
For a site $a$, $\rho_{\mathbb{X}^N}(x)\le|x-a|$. Thus \eqref{eq:three-gluing-hypothesis} gives $\|H_j(x)\|_{\mathrm{op}}\le B|x-a|^{s+1-j}$ off the sites. The exponent is at least one, and $H_j$ is zero on the sites, so $H_j$ is continuous at $a$. Its off-site continuity follows from $G,u\in C^s$ there. Hence every $H_j$ is continuous on $\mathbb{R}^d$.

We prove $D^jH_0=H_j$ by induction for $0\le j\le s$. The assertion at $j=0$ is the definition. Suppose it holds at $j-1$, where $1\le j\le s$. Off the sites $\{X_i\}_{i=1}^N$, differentiation gives $D H_{j-1}=H_j$. At a site $a$, if $\eta\ne0$ and $a+\eta\notin\mathbb{X}^N$, the preceding-order bound gives
$\|H_{j-1}(a+\eta)-H_{j-1}(a)\|_{\mathrm{op}}/|\eta|\le B|\eta|^{s+1-j}$. Consequently,
\begin{equation}
\label{eq:three-site-differentiation}
 \lim_{\substack{\eta\to0\\\eta\ne0}}
 \frac{\|H_{j-1}(a+\eta)-H_{j-1}(a)\|_{\mathrm{op}}}{|\eta|}
 =0.
\end{equation}
If $a+\eta$ is another site, its numerator is zero. Since $s+1-j\ge1$, this is the full Frechet difference-quotient estimate, uniform in the direction of $\eta$. The derivative at $a$ is the zero linear map into the preceding tensor space, identified with $H_j(a)=0$. Continuity of $H_j$ shows that $H_{j-1}$ is continuously differentiable, completing the induction. Hence $H_0\in C^s(\mathbb{R}^d)$. The site-value hypothesis and \eqref{eq:three-extended-error} give $G=u+H_0$ everywhere. Differentiating and evaluating at a site proves $D^jG(X_i)=D^ju(X_i)$ throughout the required range.

\label{lem:smoothness-top-off-sites}
Under \eqref{eq:training_data} and~\eqref{eq:doubling}, suppose $s\ge2$ and fix $\vartheta\in[0,1]$. With $C_s(D)$ defined by~\eqref{eq:three-constant-D},
\begin{equation}
\label{eq:smoothness-top-off-sites}
\|D^{s+1}F_\vartheta(x)\|_{\mathrm{op}}\le C_s(D)M,\qquad x\in\mathbb{R}^d\setminus\mathbb X^N.
\end{equation}
The estimate is uniform in the fixed parameter $\vartheta$.

Fix $x_0\notin\mathbb X^N$ and a witness $f$ satisfying~\eqref{eq:training_data}. Put $\rho\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\rho_{\mathbb X^N}(x_0)>0$, $m\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} s+1\ge3$, $\beta\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} s-1=m-2>0$, and $q\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}2s+\lceil\log_2D\rceil+2\ge2s+2$, and keep $Q\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} J_{x_0}^sf$ fixed. Lemmas~\ref{lem:three-local-errors} and~\ref{lem:three-scale} give $F_\vartheta\in C^\infty(\mathbb{R}^d\setminus\mathbb X^N)$ and $\rho\le R(x_0)\le L_{s,D}\rho$. For every $\xi\in\mathbb{R}^d$ with $|\xi|=1$, $i\in[N]$, and $|t|<1$, one has $|x_0+\rho t\xi-X_i|\ge|x_0-X_i|-\rho|t|\ge\rho(1-|t|)>0$. Hence
\begin{equation}
\label{eq:smoothness-normalized-line}
\Phi_{\xi,\vartheta}(t)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\frac{F_\vartheta(x_0+\rho t\xi)-Q(x_0+\rho t\xi)}{\beta MR(x_0)^m},\qquad |t|<1,
\end{equation}
satisfies $\Phi_{\xi,\vartheta}\in C^\infty((-1,1))$, with $\beta MR(x_0)^m\ge\beta M\rho^m>0$.

With this fixed $f,x_0,Q,\vartheta,\xi$, Lemma~\ref{lem:three-gibbs-majorants}, specifically~\eqref{eq:three-h-majorant}, gives $\Phi_{\xi,\vartheta}\preccurlyeq_n\mathcal H$ for every $n\in\mathbb N_0$. Lemma~\ref{lem:three-majorant-radius}, with $\tau\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}(64\mathrm e^{300}q)^{-1}>0$, gives $[t^n]\mathcal H(t)\ge0$ for every $n\in\mathbb N_0$ and $\mathcal H(\tau)\le8$. Thus Definition~\ref{def:three-majorization}, at order $m$, yields
\begin{equation}
\label{eq:smoothness-coefficient-bound}
\begin{aligned}
\frac{|\Phi_{\xi,\vartheta}^{(m)}(0)|}{m!}
&\le[t^m]\mathcal H(t)\le\tau^{-m}\sum_{n=0}^{\infty}\bigl([t^n]\mathcal H(t)\bigr)\tau^n\\
&=\tau^{-m}\mathcal H(\tau)\le8\tau^{-m}.
\end{aligned}
\end{equation}
Since $\deg Q\le s=m-1$, $D^mQ=0$. Differentiating~\eqref{eq:smoothness-normalized-line} and using~\eqref{eq:smoothness-coefficient-bound} gives
\begin{equation}
\label{eq:smoothness-diagonal-bound}
\begin{aligned}
|D^mF_\vartheta(x_0)[\xi^m]|
&=\beta MR(x_0)^m\rho^{-m}|\Phi_{\xi,\vartheta}^{(m)}(0)|\\
&\le8\beta M\left(\frac{R(x_0)}{\rho}\right)^m m!(64\mathrm e^{300}q)^m\\
&\le8\beta ML_{s,D}^m m!(64\mathrm e^{300}q)^m.
\end{aligned}
\end{equation}
The symmetric $m$-linear form $D^mF_\vartheta(x_0)$ therefore satisfies, by~\eqref{eq:three-polarization-bound} with $j=m$,
\begin{equation}
\label{eq:smoothness-tensor-bound}
\begin{aligned}
\|D^mF_\vartheta(x_0)\|_{\mathrm{op}}
&\le\frac{m^m}{m!}\sup_{|\xi|=1}|D^mF_\vartheta(x_0)[\xi^m]|\\
&\le\frac{m^m}{m!}\,8\beta ML_{s,D}^m m!(64\mathrm e^{300}q)^m\\
&=8\beta ML_{s,D}^m(64\mathrm e^{300}qm)^m.
\end{aligned}
\end{equation}

By~\eqref{eq:three-R-comparison}, $L_{s,D}^m\le8\,2^mD^3$. Moreover, $128<\mathrm e^5$ and $64\beta<64m<\mathrm e^{m+5}\le\mathrm e^{10m}$, since $m\ge3$ and $m\le\mathrm e^m$. Hence
\begin{equation}
\label{eq:smoothness-constant-bound}
\begin{aligned}
8\beta L_{s,D}^m(64\mathrm e^{300}qm)^m
&\le64\beta D^3(128\mathrm e^{300}qm)^m\\
&\le\mathrm e^{10m}D^3(\mathrm e^{305}qm)^m\\
&=D^3(\mathrm e^{315}qm)^m\\
&\le D^3(\mathrm e^{2000}qm)^m=C_s(D).
\end{aligned}
\end{equation}
Since $x_0\notin\mathbb X^N$ and $\vartheta\in[0,1]$ were arbitrary, \eqref{eq:smoothness-tensor-bound}--\eqref{eq:smoothness-constant-bound} give
\[
\sup_{\vartheta\in[0,1]}\sup_{x\notin\mathbb X^N}\|D^{s+1}F_\vartheta(x)\|_{\mathrm{op}}\le C_s(D)M.
\]

\label{lem:smoothness-finite-sites}
Let $V$ be a finite-dimensional normed space and let $H:\mathbb{R}^d\to V$ be continuous on $\mathbb{R}^d$ and continuously differentiable on $\mathbb{R}^d\setminus\mathbb{X}^N$. If $B\ge0$ satisfies $\|DH(x)\|_{\mathrm{op}}\le B$ for every $x\notin\mathbb{X}^N$, then
\begin{equation}
\label{eq:smoothness-finite-sites}
\|H(y)-H(x)\|_V\le B|y-x|,\qquad x,y\in\mathbb{R}^d.
\end{equation}

\label{lem:Cs1_constant_growth}
For $d\in\mathbb N_+$ and $s\in\mathbb N$, define
\begin{equation}
\label{eq:Kds-exact-growth}
K_{d,s}\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
\begin{cases}
1,&s=0,1,\\[1mm]
\displaystyle 2^{138d}\left[\mathrm{e}^{2000}(s+1)(2s+46d+2)\right]^{s+1},&s\ge2.
\end{cases}
\end{equation}
Then $K_{d,s}\ge1$ and $K_{d,s}\le\mathrm{e}^{4400d}(d+s)^{4400s}$.

If $s\in\{0,1\}$, then $d+s\ge1$ and $1=K_{d,s}\le\mathrm e^{4400d}(d+s)^{4400s}$. Suppose $s\ge2$. Since $(s+1)(2s+46d+2)\ge1$, \eqref{eq:Kds-exact-growth} gives $K_{d,s}\ge2^{138d}\mathrm e^{2000(s+1)}>1$.

Put $\ell\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\log(d+s+1)\ge\log4$. Using $s+1\le d+s+1$, $2s+46d+2\le46(d+s+1)$, $138\log2<96$, and $\log46<4$, we obtain
\[
\begin{aligned}
\log K_{d,s}
&=138d\log2+(s+1)\bigl(2000+\log(s+1)+\log(2s+46d+2)\bigr)\\
&\le138d\log2+(s+1)\bigl(2000+\log46+2\ell\bigr)\\
&\le96d+(s+1)(2004+2\ell)\\
&\le96d+3006s+3s\ell,
\end{aligned}
\]
where $s+1\le3s/2$ was used in the last line. Since $3006\le2197\log4\le2197\ell$, one has $3006s+3s\ell\le2200s\ell$. Moreover, $d+s\ge3$ implies $d+s+1\le(d+s)^2$, hence $\ell\le2\log(d+s)$. Therefore,
\begin{equation}
\label{eq:de_estimatoski}
\begin{aligned}
\log K_{d,s}
&\le96d+2200s\ell\\
&\le2200d+4400s\log(d+s)\\
&\le4400d+4400s\log(d+s).
\end{aligned}
\end{equation}
Exponentiating~\eqref{eq:de_estimatoski} yields $K_{d,s}\le\mathrm e^{4400d}\mathrm e^{4400s\log(d+s)}=\mathrm e^{4400d}(d+s)^{4400s}$.

Recall from~\eqref{eq:entropy-variance-extension__specialization} that the calibrated reconstruction is $F=F_1$. We treat separately the cases $s=0$, $s=1$, and $s\ge2$.

Suppose first that $s=0$. By Lemma~\ref{lem:three-zero-order}, $F\in C(\mathbb{R}^d)$ and $|F(x)-F(y)|\le M|x-y|$ for all $x,y\in\mathbb{R}^d$. Since $D^0F=F$, Definition~\eqref{eq:Lip_Seminorm} yields $[F]_{0,1}\le M$, and therefore $F\in\dot C^{0,1}(\mathbb{R}^d)$.

Suppose next that $s=1$. Lemma~\ref{lem:three-first-order} yields $F\in C^1(\mathbb{R}^d)$ and $|\nabla F(x)-\nabla F(y)|\le M|x-y|$ for all $x,y\in\mathbb{R}^d$. For fixed $x,y\in\mathbb{R}^d$, put $g_{x,y}\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\nabla F(x)-\nabla F(y)$. Since $(DF(x)-DF(y))[v]=g_{x,y}\cdot v$, Cauchy-Schwarz and, when $g_{x,y}\ne0$, the choice $v=g_{x,y}/|g_{x,y}|$ give $\|DF(x)-DF(y)\|_{\mathrm{op}}=|g_{x,y}|$. The same identity is immediate when $g_{x,y}=0$. Hence $[F]_{1,1}\le M$, and therefore $F\in\dot C^{1,1}(\mathbb{R}^d)$.

Assume henceforth that $s\ge2$ and fix an arbitrary $\vartheta\in[0,1]$. By Setting~\ref{TheSetting}, $f\in\dot C^{s,1}(\mathbb{R}^d)\subset C^s(\mathbb{R}^d)$ and $P_i=J_{X_i}^sf$ for every $i\in[N]$. Moreover,~\eqref{eq:entropy-variance-extension__primal___SITES} gives $F_\vartheta(X_i)=P_i(X_i)=f(X_i)$ for every $i\in[N]$. Lemma~\ref{lem:three-local-errors} gives
\begin{equation}
\label{eq:smoothness-family-local-errors}
F_\vartheta\in C^\infty(\mathbb{R}^d\setminus\mathbb X^N),\qquad \|D^jF_\vartheta(x)-D^jf(x)\|_{\mathrm{op}}\le C_s(D)M\rho_{\mathbb X^N}(x)^{s+1-j}
\end{equation}
for every $x\in\mathbb{R}^d\setminus\mathbb X^N$ and $0\le j\le s$. Thus the hypotheses of Lemma~\ref{lem:three-site-gluing} hold with $G=F_\vartheta$, $u=f$, and $B=C_s(D)M$. Consequently,
\begin{equation}
\label{eq:smoothness-family-Cs-and-jets}
F_\vartheta\in C^s(\mathbb{R}^d),\qquad D^jF_\vartheta(X_i)=D^jf(X_i)=D^jP_i(X_i),\qquad i\in[N],\quad0\le j\le s.
\end{equation}

Let $V_s\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\operatorname{Sym}^s(\mathbb{R}^d;\mathbb{R})$ be the finite-dimensional normed space of symmetric $s$-linear forms on $\mathbb{R}^d$, equipped with $\|\cdot\|_{\mathrm{op}}$, and set $H_\vartheta\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} D^sF_\vartheta:\mathbb{R}^d\to V_s$. By~\eqref{eq:smoothness-family-Cs-and-jets}, $H_\vartheta$ is continuous on $\mathbb{R}^d$, while~\eqref{eq:smoothness-family-local-errors} implies that it is continuously differentiable on $\mathbb{R}^d\setminus\mathbb X^N$. For $x\notin\mathbb X^N$ and $u,v_1,\ldots,v_s\in\mathbb{R}^d$, one has $(DH_\vartheta(x)[u])[v_1,\ldots,v_s]=D^{s+1}F_\vartheta(x)[u,v_1,\ldots,v_s]$. Hence, by Lemma~\ref{lem:smoothness-top-off-sites},
$$
\begin{aligned}
\|DH_\vartheta(x)\|_{\mathrm{op}}&=\sup_{|u|\le1}\|DH_\vartheta(x)[u]\|_{\mathrm{op}}\\
&=\sup_{|u|\le1}\ \sup_{|v_1|,\ldots,|v_s|\le1}|D^{s+1}F_\vartheta(x)[u,v_1,\ldots,v_s]|\\
&=\|D^{s+1}F_\vartheta(x)\|_{\mathrm{op}}\le C_s(D)M,
\end{aligned}
\qquad x\in\mathbb{R}^d\setminus\mathbb X^N.
$$
Lemma~\ref{lem:smoothness-finite-sites}, applied to $H_\vartheta$ with $B=C_s(D)M$, therefore gives $\|D^sF_\vartheta(y)-D^sF_\vartheta(x)\|_{\mathrm{op}}\le C_s(D)M|y-x|$ for all $x,y\in\mathbb{R}^d$. Combining this estimate with~\eqref{eq:smoothness-family-Cs-and-jets} and Definition~\eqref{eq:Lip_Seminorm} yields
\begin{equation}
\label{eq:smoothness-family-bound}
F_\vartheta\in\dot C^{s,1}(\mathbb{R}^d),\qquad [F_\vartheta]_{s,1}\le C_s(D)M.
\end{equation}
The constants in Lemmas~\ref{lem:three-local-errors} and~\ref{lem:smoothness-top-off-sites} are independent of the fixed parameter $\vartheta$. Since $\vartheta\in[0,1]$ was arbitrary,
\begin{equation}
\label{eq:smoothness-family-uniform-bound}
\sup_{\vartheta\in[0,1]}[F_\vartheta]_{s,1}\le C_s(D)M.
\end{equation}
The geometry fixed in Theorem~\ref{thrm:main} has $D=2^{46d}$. Since $46d\in\mathbb N$, Definition~\eqref{eq:three-constant-D} gives
\begin{equation}
\label{eq:smoothness-constant-specialization}
\begin{aligned}
C_s(2^{46d})&=(2^{46d})^3\left[\mathrm e^{2000}(s+1)\bigl(2s+\lceil\log_2(2^{46d})\rceil+2\bigr)\right]^{s+1}\\
&=2^{138d}\left[\mathrm e^{2000}(s+1)(2s+46d+2)\right]^{s+1}.
\end{aligned}
\end{equation}
Taking $\vartheta=1$ in~\eqref{eq:smoothness-family-bound} and using $F=F_1$, then combining with the cases $s=0,1$, proves
\begin{equation}
\label{eq:smoothness-all-orders}
[F]_{s,1}\le\begin{cases}M,&s=0,1,\\[1mm]2^{138d}\left[\mathrm e^{2000}(s+1)(2s+46d+2)\right]^{s+1}M,&s\ge2,\end{cases}=K_{d,s}M.
\end{equation}
The constant in~\eqref{eq:smoothness-all-orders} is precisely the one defined in~\eqref{eq:Kds-exact-growth}. Lemma~\ref{lem:Cs1_constant_growth} further gives $1\le K_{d,s}\le\mathrm e^{4400d}(d+s)^{4400s}$, which proves the asserted dependence on $d,s$ and completes the proof.

Write $\widetilde F\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} F_{\operatorname{ext}}$.
Put $U\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\mathbb{R}^d\setminus\mathbb X^N$ and fix $x\in U$. Since $s\ge2$, $M>0$, and $R(x)>0$, define
\begin{equation}
\label{eq:entropy-only-data}
a_i(x)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} P_i(x)+\frac{A_sM|x-X_i|^{2s}}{R(x)^{s-1}},\qquad \tau(x)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}(s-1)MR(x)^{s+1}>0.
\end{equation}
Because $0\in\mathcal I_s$, Definition~\eqref{eq:entropy-variance-extension__primal} yields
\begin{equation}
\label{eq:entropy-only-zero-primal}
F_0(x)=\min_{\lambda\in\Delta_N}\left\{\sum_{i=1}^N\lambda_i a_i(x)+\tau(x)\operatorname{KL}(\lambda\mid\theta(x))\right\}.
\end{equation}
Since $\theta_i(x)>0$ and $\sum_i\theta_i(x)=1$, define
\begin{equation}
\label{eq:entropy-only-gibbs-measure}
Z(x)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\sum_{i=1}^N\theta_i(x)\exp\!\left(-\frac{a_i(x)}{\tau(x)}\right)>0,\qquad \nu_i(x)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\frac{\theta_i(x)\exp(-a_i(x)/\tau(x))}{Z(x)}.
\end{equation}
Then $\nu_i(x)>0$ for every $i$ and $\sum_i\nu_i(x)=1$, so $\nu(x)\in\Delta_N^\circ$.

Let $\lambda\in\Delta_N$ and put $I_\lambda\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\{i\in[N]:\lambda_i>0\}$. Since $\theta_i(x),\nu_i(x)>0$, one has $\log(\nu_i(x)/\theta_i(x))=-a_i(x)/\tau(x)-\log Z(x)$ for every $i$. Coordinates outside $I_\lambda$ contribute zero to both relative entropies by the convention $0\log0=0$. Therefore,
\begin{equation}
\label{eq:entropy-only-KL-decomposition}
\begin{aligned}
\tau(x)\operatorname{KL}(\lambda\mid\nu(x))&=\tau(x)\sum_{i\in I_\lambda}\lambda_i\left[\log\frac{\lambda_i}{\theta_i(x)}-\log\frac{\nu_i(x)}{\theta_i(x)}\right]\\
&=\tau(x)\operatorname{KL}(\lambda\mid\theta(x))+\sum_{i=1}^N\lambda_i a_i(x)+\tau(x)\log Z(x).
\end{aligned}
\end{equation}
To treat boundary points of $\Delta_N$, put $t_i\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\lambda_i/\nu_i(x)\in[0,\infty)$ and define
$$
\phi(t)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\begin{cases}t\log t-t+1,&t>0,\\1,&t=0.\end{cases}
$$
The convention at zero agrees with $\lim_{t\downarrow0}t\log t=0$. On $(0,\infty)$, $\phi'(t)=\log t$ and $\phi''(t)=1/t>0$, so $\phi(t)\ge\phi(1)=0$, with equality exactly at $t=1$; moreover, $\phi(0)=1>0$. Since $t\log t=\phi(t)+t-1$ on $[0,\infty)$ under the convention $0\log0=0$, one has
\begin{equation}
\label{eq:entropy-only-KL-nonnegative}
\begin{aligned}
\operatorname{KL}(\lambda\mid\nu(x))&=\sum_{i=1}^N\nu_i(x)t_i\log t_i\\
&=\sum_{i=1}^N\nu_i(x)\phi(t_i)+\sum_{i=1}^N\lambda_i-\sum_{i=1}^N\nu_i(x)\\
&=\sum_{i=1}^N\nu_i(x)\phi(t_i)\ge0.
\end{aligned}
\end{equation}
Because every $\nu_i(x)>0$, equality in~\eqref{eq:entropy-only-KL-nonnegative} holds precisely when $t_i=1$ for every $i$, that is, when $\lambda=\nu(x)$. Since $\tau(x)>0$, equations~\eqref{eq:entropy-only-zero-primal} and~\eqref{eq:entropy-only-KL-decomposition} show that $\nu(x)$ is the unique minimizer of the $\vartheta=0$ objective and
\begin{equation}
\label{eq:entropy-only-value}
F_0(x)=-\tau(x)\log Z(x).
\end{equation}

By~\eqref{eq:entropy-only-data},
$$
\begin{aligned}
\frac{a_i(x)}{\tau(x)}&=\frac{P_i(x)}{(s-1)MR(x)^{s+1}}+\frac{A_sM|x-X_i|^{2s}}{(s-1)MR(x)^{s-1}R(x)^{s+1}}=\frac1{s-1}\left[\frac{P_i(x)}{MR(x)^{s+1}}+A_s\left(\frac{|x-X_i|}{R(x)}\right)^{2s}\right].
\end{aligned}
$$
Substituting this identity and $\tau(x)=(s-1)MR(x)^{s+1}$ into~\eqref{eq:entropy-only-value} gives exactly~\eqref{eq:ExtenstionFormula_Expression} on $U$. At every site $X_i$, the site definitions give $F_0(X_i)=P_i(X_i)=\widetilde F(X_i)$. Hence
\begin{equation}
\label{eq:entropy-only-equals-family}
\widetilde F=F_0\qquad\text{on }\mathbb{R}^d.
\end{equation}
If $D=2^{46d}$ and $\mu\in\Delta_{N:D}$, Proposition~\ref{prop:variance-parameter-family}, applied with $\vartheta=0$, gives $D^j\widetilde F(X_i)=D^jP_i(X_i)$ for every $i\in[N]$ and $0\le j\le s$, together with $\widetilde F\in\dot C^{s,1}(\mathbb R^d)$ and $[\widetilde F]_{s,1}\le K_{d,s}M$.

Under the original hypotheses, we next verify off-site real analyticity.  
For $\gamma\ge0$, set $S_\gamma(x)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\sum_{i=1}^N\mu_i|x-X_i|^{-\gamma}$ for $x\in U$. For every $i$, the polynomial $\sigma_i(x)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\sum_{k=1}^d(x_k-X_{i,k})^2$ is strictly positive on $U$. Since $t\mapsto t^{1/2}$ is real analytic on $(0,\infty)$, $r_i(x)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}|x-X_i|=\sigma_i(x)^{1/2}$ is positive and real analytic on $U$. Hence $S_q$ and $S_{q-p}$ are positive real-analytic functions on $U$. From the definitions of $\theta$ and $R$,
\begin{equation}
\label{eq:entropy-only-R-ratio}
R(x)^p=\sum_{i=1}^N\theta_i(x)r_i(x)^p=\frac{\sum_{i=1}^N\mu_i r_i(x)^{p-q}}{S_q(x)}=\frac{S_{q-p}(x)}{S_q(x)}>0.
\end{equation}
Since $t\mapsto t^{1/p}$ is real analytic on $(0,\infty)$,~\eqref{eq:entropy-only-R-ratio} implies that $R$ is positive and real analytic on $U$. The identity $\theta_i(x)=\mu_i r_i(x)^{-q}/S_q(x)$ then shows that every $\theta_i$ is real analytic on $U$. It follows from~\eqref{eq:entropy-only-data} that each $a_i$ and $\tau$ is real analytic on $U$, with $\tau>0$. Consequently, each function $x\mapsto\theta_i(x)\exp(-a_i(x)/\tau(x))$ is positive and real analytic on $U$, so their finite sum $Z$ is positive and real analytic. Since $\log$ is real analytic on $(0,\infty)$,~\eqref{eq:entropy-only-value} yields $\widetilde F|_U=-\tau\log Z\in C^\omega(U)$.

We finally prove that $\widetilde F$ is definable in $\mathbb{R}_{\operatorname{exp}}$. The set $U=\mathbb{R}^d\setminus\{X_1,\ldots,X_N\}$ is semialgebraic and hence definable in $\mathbb{R}_{\operatorname{exp}}$. The graph of the positive distance $r_i$ on $U$ is the semialgebraic set
$$
\left\{(x,r)\in U\times(0,\infty):r^2=\sum_{k=1}^d(x_k-X_{i,k})^2\right\},
$$
and is therefore definable. Because $p,q,q-p\in\mathbb N_+$ and each $r_i$ is positive on $U$, the functions $r_i^{-q}$, $S_q$, $S_{q-p}$, and $\theta_i$ are definable there. By~\eqref{eq:entropy-only-R-ratio}, the graph of $R$ on $U$ is the definable set
$$
\left\{(x,r)\in U\times(0,\infty):r^pS_q(x)=S_{q-p}(x)\right\}.
$$
Hence the functions $a_i$ and $\tau$ in~\eqref{eq:entropy-only-data} are definable on $U$. Since the exponential map belongs to the language of $\mathbb{R}_{\operatorname{exp}}$, the function $Z$ in~\eqref{eq:entropy-only-gibbs-measure} is definable. The graph of $\log$ on $(0,\infty)$ is the definable set $\{(z,y)\in(0,\infty)\times\mathbb{R}:\exp(y)=z\}$, so $\log$ is definable there. It follows that
$$
\Gamma_U\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\{(x,y)\in U\times\mathbb{R}:y=-\tau(x)\log Z(x)\}
$$
is definable. The finite set $\Gamma_{\mathbb X^N}\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\bigcup_{i=1}^N\{(X_i,P_i(X_i))\}$ is also definable, and~\eqref{eq:entropy-only-equals-family} gives $\operatorname{graph}(\widetilde F)=\Gamma_U\cup\Gamma_{\mathbb X^N}$. Thus $\widetilde F$ is definable in $\mathbb{R}_{\operatorname{exp}}$. Every parameter appearing in its graph is one of the site coordinates, a coefficient of one of the polynomials $P_i$, $M$, or one of the weights $\mu_i$; the witness $f$ does not enter the defining formula.

\label{lem:finite-whitney-seminorm__bound}
Fix $d,N\in\mathbb N_+$ and $s\in\mathbb N$. Let $X_1,\ldots,X_N\in\mathbb R^d$ be distinct, and let $P_1,\ldots,P_N$ be real polynomials of degree at most $s$. For $\mathbb D^N=\{(X_i,P_i)\}_{i=1}^N$, 

let $W_{\mathbb D^N}$ be defined by~\eqref{eq:finite-whitney-seminorm}, and set
\begin{equation}
\label{eq:explicit-whitney-calibration-constant}
\kappa_{d,s}\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
\begin{cases}
1 & \mbox{ : if }s=0,\\[1mm]
2^{138d+3}d^{s/2}
\bigl[128(s+1)(2s+46d+2)\bigr]^{s+1}&  \mbox{ : if } s\ge1.
\end{cases}
\end{equation}
Then:
\begin{enumerate}
\item[(i)] Every $f\in\dot C^{s,1}(\mathbb R^d)$ satisfying
$J_{X_i}^sf=P_i$ for all $i\in[N]$ obeys
$W_{\mathbb D^N}\le[f]_{s,1}$.
\item[(ii)] There exists $g\in\dot C^{s,1}(\mathbb R^d)$ such that
$J_{X_i}^sg=P_i$ for all $i\in[N]$ and
$[g]_{s,1}\le\kappa_{d,s}W_{\mathbb D^N}$.
\item[(iii)] $W_{\mathbb D^N}=0$ if and only if all $P_i$
coincide. In this case one may take $g=P_1$.
\end{enumerate}
Moreover, for $s\ge1$, the constant satisfies $1\le\kappa_{d,s}\le\mathrm{e}^{100d}(d+s)^{32s}$.

Fix $i\in[N]$. Theorem~\ref{thrm:main}(i)-(ii) gives $J_{X_i}^sF=P_i$ and $[F]_{s,1}\le K_{d,s}M$. Lemma~\ref{lem:three-taylor}, applied on $\mathbb R^d$, and the finite Taylor expansion of $D^rP_i$ at $X_i$ therefore give, for $x\in[0,1]^d$ and $0\le r\le s$,
\begin{equation}
\label{eq:full-Cs1-derivative-control}
\begin{aligned}
 \|D^rF(x)\|_{\mathrm{op}}
 &\le \|D^rP_i(x)\|_{\mathrm{op}}
       +\frac{K_{d,s}M}{(s+1-r)!}|x-X_i|^{s+1-r}\\
 &\le \sum_{k=0}^{s-r}\frac{\|D^{r+k}P_i(X_i)\|_{\mathrm{op}}}{k!}|x-X_i|^k
       +\frac{K_{d,s}M}{(s+1-r)!}|x-X_i|^{s+1-r}.
\end{aligned}
\end{equation}
Since $|x-X_i|\le\sqrt d$ and $\operatorname{Lip}_{[0,1]^d}(D^sF)\le[F]_{s,1}$, summing in $r$ and collecting terms with the same derivative order yields
\[
\begin{aligned}
 \|F\|_{C^{s,1}([0,1]^d)}
 &\le \sum_{j=0}^s\|D^jP_i(X_i)\|_{\mathrm{op}}
           \sum_{k=0}^j\frac{d^{k/2}}{k!}
       +K_{d,s}M\sum_{k=0}^{s+1}\frac{d^{k/2}}{k!}\\
 &\le \mathrm e^{\sqrt d}\left(
       \sum_{j=0}^s\|D^jP_i(X_i)\|_{\mathrm{op}}+K_{d,s}M\right).
\end{aligned}
\]
Taking the minimum over $i\in[N]$ proves~\eqref{eq:full-Cs1-control}. For $s=0$, the first estimate is the Lipschitz inequality based at $X_i$; for $r=s$, its remainder is $K_{d,s}M|x-X_i|$. The proof also covers $N=1$ and sites on the boundary of the cube.

\label{lem:three-gradient-lipschitz}
Let $\Omega\subset\mathbb{R}^d$ be nonempty, open and convex and let $u\in C^1(\Omega)$. Then, with both sides allowed to be infinite,
\begin{equation}
\label{eq:three-gradient-lipschitz}
 \operatorname{Lip}_\Omega(u)=\sup_{x\in\Omega}|\nabla u(x)|.
\end{equation}
If $u$ is $C^1$ on an open neighborhood of the compact set $\overline\Omega$, then the quantities in \eqref{eq:three-gradient-lipschitz} are finite.

We exhibit a circuit computing $F_{\operatorname{ext}}$ by first exhibiting a long list of sub-circuits which execute ``sub-routines'' of the overall algorithm.  These are then ``wired together'' into a larger more complicated algorithm performing the computation.  We first compile a circuit computing $F_{\operatorname{ext}}$ on $U\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} \mathbb{R}^d\setminus \{X_n\}_{n=1}^N$, which we then ``wire into'' a larger circuit computing the whole extension on all of $\mathbb{R}^d$.

Naturally, parallelism is of course a core component of achieving the logarithmic run-time of our algorithm.  We exhibit illustrations of the more complicated sub-circuits in our construction to streamline the communication of our proof; but we do not illustrate the most standard sub-circuits such as (padded) complete binary trees implementing $2\le m$-fold products.

Every displayed affine map is expanded into constant and binary arithmetic gates. Likewise, squaring on $\mathbb R$ is implemented by three gates computing $0=\mathsf c_0(t)$, $t+0$, and $t(t+0)$, respectively.

\paragraph{Computing: $m$-ary summation, products, and the Euclidean norm:}

We first make some standard observations.  We note that our proof is not geared towards maximal efficiency; but rather ``humanly-comprehensible clarity''.  

For $m\in\mathbb N_+$, put $h_m\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\lceil\log_2m\rceil$ and $\bar m\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}2^{h_m}$. Let $(V,E_T)$ be a complete binary tree of height $h_m$, with leaves $v_1<\cdots<v_{\bar m}$ and edges directed towards its root. Define
$$
E\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} E_T\cup\{(v_1,v_i):m<i\le\bar m\}
\qquad\mbox{ and }\qquad
g_v\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
\begin{cases}
\operatorname{Id}_{\mathbb R},&v\in\{v_1,\ldots,v_m\},\\
\mathsf c_0,&v\in\{v_i:m<i\le\bar m\},\\
+_2,&v\in V\setminus\{v_1,\ldots,v_{\bar m}\}.
\end{cases}
$$
Consider the $(+_2,\mathsf c_0,\operatorname{Id}_{\mathbb{R}})$-circuit 
$\mathcal C_{+,m}\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}(V,E,(g_v)_{v\in V})$, equipped with $\Pi\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} I_m$, has exactly $m$ input vertices. Its tree leaves evaluate to $u_i$ for $i\le m$ and to zero otherwise, so it computes $\operatorname{SUM}_m(u)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\sum_{i=1}^m u_i$ on $\mathbb R^m$. Moreover,
$$
|\mathcal C_{+,m}|=2\bar m-m-1,
\qquad
\operatorname{depth}(\mathcal C_{+,m})=h_m+\mathbf 1_{\{m<\bar m\}},
\qquad
\operatorname{width}(\mathcal C_{+,m})\le\bar m.
$$
Since $m\le\bar m<2m$, size and width are $O(m)$, and depth is $O(\log m)$ for $m\ge2$; for $m=1$, size and depth are zero.
Note that, replacing $+_2$ by $\times_2$ and $\mathsf c_0$ by $\mathsf c_1$ gives a 
$(\times_2,\mathsf c_1,\operatorname{Id}_{\mathbb{R}})$-circuit computing $\operatorname{Prod}_m(u)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\prod_{i=1}^m u_i$ on $\mathbb R^m$, with the same lifting channel and complexity bounds.

A very similar construction also exhibits a $(\cdot^2,\cdot^{1/2},+_2)$-circuit computing $\|\cdot\|_2$ on all of $\mathbb{R}^m$; with depth $\mathcal{O}(\log(m))$, width $\mathcal{O}(m)$, and size $\mathcal{O}(m)$.  Note that, in particular $|\cdot|$ is computed by a $(\cdot^2,\cdot^{1/2})$-circuit of depth, width, and size $\mathcal{O}(1)$.

\paragraph{Computing point indicators:}
Fix $m\in\mathbb N_+$ and $b\in\mathbb R^m$. Let $\mathcal C_{\times,m}\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}(V_\times,E_\times,(g_v^\times)_{v\in V_\times})$ be the product circuit constructed above, with input vertices $v_1,\ldots,v_m$. Adjoin fresh vertices $w_1<\cdots<w_m$ and define
\[
V\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} V_\times\cup\{w_1,\ldots,w_m\}
\qquad
\mbox{ and }
\qquad
E\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} E_\times\cup\{(w_i,v_i):i\in[m]\}
\]
with gates given by 
\[
g_v\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
\begin{cases}
\operatorname{Id}_{\mathbb R},&v=w_i,\ i\in[m],\\
I_{\cdot=b_i},&v=v_i,\ i\in[m],\\
g_v^\times,&v\in V_\times\setminus\{v_1,\ldots,v_m\}.
\end{cases}
\]
Equip $\mathcal C_{=,b}\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}(V,E,(g_v)_{v\in V})$ with $\Pi\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} I_m$ on the input vertices $(w_i)_{i=1}^m$. Its original input leaves now evaluate to $I_{\cdot=b_i}(x_i)$; whence for every $x\in\mathbb R^m$ we have
$$
f_{\mathcal C_{=,b},I_m}(x)
=\prod_{i=1}^m I_{\cdot=b_i}(x_i)
=I_{\cdot=b}(x).
$$
Moreover, $\mathcal C_{=,b}$ has size 
$2\bar m-1\in \mathcal{O}(m)$, width at-most $\bar m\in \mathcal{O}(m)$, and depth $
=h_m+1+\mathbf 1_{\{m<\bar m\}} \in \mathcal{O}(\log(m))$.


\paragraph{Computing the polynomials $P_i$:}
For $s\ge2$, put $\Lambda\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\{\alpha\in\mathbb N_0^d:|\alpha|\le s\}$, $B\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}|\Lambda|=\binom{d+s}{s}$, and $\bar B\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}2^{h_B}$. Write $P_i(x)=\sum_{\alpha\in\Lambda}c_{i,\alpha}x^\alpha$. For each $\alpha\in\Lambda$ with $|\alpha|\ge2$, choose $\beta_\alpha,\gamma_\alpha\in\Lambda$ satisfying $\beta_\alpha+\gamma_\alpha=\alpha$, $|\beta_\alpha|=\lfloor|\alpha|/2\rfloor$, and $|\gamma_\alpha|=\lceil|\alpha|/2\rceil$. Define
$$
V_0\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\{v_\alpha:\alpha\in\Lambda\setminus\{0\}\}
\qquad\mbox{ and }\qquad
E_0\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\bigcup_{\substack{\alpha\in\Lambda\\|\alpha|\ge2}}
\{(v_{\beta_\alpha},v_\alpha),(v_{\gamma_\alpha},v_\alpha)\},
$$
with gates given by
\[
g_{v_\alpha}\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
\begin{cases}
\operatorname{Id}_{\mathbb R},&|\alpha|=1,\\
\cdot^2,&|\alpha|\ge2,\ \beta_\alpha=\gamma_\alpha,\\
\times_2,&|\alpha|\ge2,\ \beta_\alpha\ne\gamma_\alpha.
\end{cases}
\]
Equip the input vertices $v_{e_1}<\cdots<v_{e_d}$ with $\Pi\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} I_d$, taking squaring on all of $\mathbb R$. Induction on $|\alpha|$ shows that $v_\alpha$ evaluates to $x^\alpha$ and, after scalar expansion, has depth at most $3h_{|\alpha|}$.
For each $\alpha\in\Lambda$, attach a constant vertex $\kappa_\alpha$ carrying $\mathsf c_{c_{i,\alpha}}$ to $v_{e_1}$. For $\alpha\ne0$, add a $\times_2$-vertex $t_\alpha$ with parents $\kappa_\alpha$ and $v_\alpha$, and set $t_0\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\kappa_0$. Attach the summation subcircuit $\mathcal C_{+,B}$ to $(t_\alpha)_{\alpha\in\Lambda}$, ordering $0$ first. The resulting circuit $\mathcal C_{P_i}$ computes $P_i$ on $\mathbb R^d$\footnote{A similar construction holds for non-constant univariate polynomials.}.
Each of the $B-d-1$ monomial operations uses at most three gates. There are also $B$ constant gates, $B-1$ coefficient products, and $2\bar B-B-1$ summation gates. Consequently, after scalar expansion, $\mathcal C_{P_i}$ has size $\mathcal O(B)$, depth at most $3h_s+h_B+1=\mathcal O(\log B)$, and width at most $d+|\mathcal C_{P_i}|=\mathcal O(B)$.



