(v_{2,3},v_{3,2})\}\\
&\quad\cup\{(v_{3,j},v_{4,j}),(v_{4,j},v_{5,1}):j\in[2]\}.
\end{aligned}
$$
Assign the maps
$$
g_v=
\begin{cases}
\operatorname{Id}_{\mathbb R^d},&v=v_0,\\
P_j,&v=v_{1,j},\\
E_{\operatorname{exp}},&v=v_{2,1},\\
\theta,&v=v_{2,2},\\
R,&v=v_{2,3},\\
\langle\cdot,\cdot\rangle_{\mathbb R^N},&v=v_{3,1},\\
\cdot^{s+1},&v=v_{3,2},\\
\log,&v=v_{4,1},\\
(1-s)M\cdot,&v=v_{4,2},\\
\times_2,&v=v_{5,1}.
\end{cases}
$$
Each displayed map is implemented by its scalar subcircuit, with the inner product using $N$ parallel $\times_2$ gates followed by $\mathcal C_{+,N}$. The inputs of $v_{2,1}$ are ordered as $(P_1(x),\ldots,P_N(x),x)$. The input block expands into $d$ identity vertices with lifting channel $\Pi=I_d$.
Upon writing $P(x)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}(P_1(x),\ldots,P_N(x))$, we obtain
$$
f_{\mathcal C_{\operatorname{ext}},I_d}(x)
=(1-s)MR(x)^{s+1}
\log\left(
\sum_{j=1}^N\theta_j(x)
E_{\operatorname{exp},j}(P(x),x)
\right)
=F_{\operatorname{ext}}(x),
\qquad x\in U.
$$
The logarithm is well-defined since $\theta(x)\in\Delta_N$ and every coordinate of $E_{\operatorname{exp}}(P(x),x)$ is positive. For fixed $d,s$, the expanded circuit has size and width $\mathcal O(N)$, and depth $\mathcal O(\log N)$ for $N\ge2$; for $N=1$, all three are $\mathcal O(1)$.


\paragraph{Compiling the Circuit Computing $F_{\operatorname{ext}}$:}
Put $H\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} F_{\operatorname{ext}}|_U$, computed by the preceding circuit, and choose
$
a\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\left(1+\sum_{i=1}^N |(X_i)_1|\right)e_1\in U.
$
Since the sites are distinct,
$
\chi(x)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}1-\sum_{i=1}^N I_{\cdot=X_i}(x)=I_U(x)
$.
Define $S_a(x,t)\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} a+t(x-a)$, implemented coordinatewise using affine gates and $\times_2$. Then $S_a(x,\chi(x))=x$ on $U$ and equals $a$ at every site. Consequently, every evaluation of $H$ in the identity
\begin{equation}
\label{eq:basic_idenity}
F_{\operatorname{ext}}(x)
=
\sum_{i=1}^N I_{\cdot=X_i}(x)P_i(x)
+
\chi(x)\,H\bigl(S_a(x,\chi(x))\bigr)
\end{equation}
is well-defined for each $x\in\mathbb R^d$.

