We now implement the ``master'' circuit in Figure~\ref{fig:F_ext__finished} using the identity in~\eqref{eq:basic_idenity} and all our sub-circuits constructed thus far to compute $F_{\operatorname{ext}}$ on all of $\mathbb{R}^d$.

Consider the DAG of subcircuits $\widehat{\mathcal C}_{\operatorname{ext}}\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}(V,E,(g_v)_{v\in V})$, with input block $v_0$ carrying $x$ and designated output $r_5$, where
$$
\begin{aligned}
V
&=\{v_0,r_0,\ldots,r_5\}
\cup\{v_{i,j}:i\in[3],\,j\in[N]\},\\
E
&=\bigcup_{j=1}^N
\bigl\{
(v_0,v_{1,j}),(v_0,v_{2,j}),
(v_{1,j},v_{3,j}),(v_{2,j},v_{3,j}),
(v_{1,j},r_0),(v_{3,j},r_5)
\bigr\}\\
&\quad\cup
\bigl\{
(r_0,r_1),(v_0,r_2),(r_1,r_2),(r_2,r_3),
(r_1,r_4),(r_3,r_4),(r_4,r_5)
\bigr\}.
\end{aligned}
$$
Assign the maps
$$
g_v=
\begin{cases}
\operatorname{Id}_{\mathbb R^d},&v=v_0,\\
I_{\cdot=X_j},&v=v_{1,j},\\
P_j,&v=v_{2,j},\\
\times_2,&v\in\{v_{3,j}:j\in[N]\}\cup\{r_4\},\\
\operatorname{SUM}_N,&v=r_0,\\
1-\cdot,&v=r_1,\\
S_a,&v=r_2,\\
H,&v=r_3,\\
\operatorname{SUM}_{N+1},&v=r_5.
\end{cases}
$$
Each displayed map uses its scalar subcircuit, with the inputs of $r_2$ ordered as $(x,\chi(x))$. The input block expands into $d$ identity vertices with lifting channel $\Pi=I_d$. The vertices $v_{3,j}$ and $r_4$ evaluate to $I_{\cdot=X_j}(x)P_j(x)$ and $\chi(x)H(S_a(x,\chi(x)))$, respectively. Hence~\eqref{eq:basic_idenity} gives
$$
f_{\widehat{\mathcal C}_{\operatorname{ext}},I_d}(x)
=F_{\operatorname{ext}}(x),
\qquad x\in\mathbb R^d.
$$
For fixed $d,s$, the expanded circuit has size and width $\mathcal O(N)$, and depth $\mathcal O(\log N)$ for $N\ge2$; for $N=1$, all three are $\mathcal O(1)$.


\paragraph{The Final Tally:}
Put $B_{d,s}\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\binom{d+s}{s}=\mathcal O_s(d^s)$. The master circuit contains $2N$ polynomial subcircuits, each having size $\mathcal O(B_{d,s})$ and depth $\mathcal O(\log B_{d,s})$ after scalar expansion. All remaining subcircuits together contribute $\mathcal O(Nd)$ gates and at most $\mathcal O(\log(d+N))$ further depth. Consequently,
$$
\begin{aligned}
|\widehat{\mathcal C}_{\operatorname{ext}}|
&=\mathcal O(NB_{d,s}+Nd)
=\mathcal O_s(Nd^s),\\
\operatorname{depth}(\widehat{\mathcal C}_{\operatorname{ext}})
&=\mathcal O(\log B_{d,s}+\log(d+N))
=\mathcal O_s(\log(d+N)),\\
\operatorname{width}(\widehat{\mathcal C}_{\operatorname{ext}})
&\le d+|\widehat{\mathcal C}_{\operatorname{ext}}|
=\mathcal O_s(Nd^s).
\end{aligned}
$$
These bounds include the point-indicator subcircuits and the input adjustment $S_a$, which ensure that the realization domain is all of $\mathbb R^d$.

\label{lem:compiler-ram-implementation}
Fix $d,s\in\mathbb N_+$ with $s\ge2$. For an input satisfying Data Format~\ref{dataformat}, use the scalar emitters and three relabelling scans of Algorithm~\ref{alg:compile-circuit}, and put
\[
B=\binom{d+s}{s},\qquad L=B+d+1,\qquad H_0=NL,\qquad K_0=160H_0.
\]
Let $K$ count all emitted vertices. For each table-bearing call $F$, including the compiler frame, let $m_F$ be its port count and $L_F$ its number of emitted vertices, including nested calls. Let $J$ be the maximum number of simultaneously active calls, and let $m_\rho$ be the input count of a reduction call. If
\[
\begin{gathered}
K\le16NB+140Nd,\qquad J\le8,\\
\max_Fm_F\le\max\{N+d+1,B\},\qquad \max_\rho m_\rho\le\max\{B,d,N+1\}.
\end{gathered}
\]
then, there exists a finite exact-real word-RAM program $\mathcal P_{d,s}$, independent of $N,q,w$ and the real input values, implementing these emissions and scans whenever~\eqref{eq:compiler-word-capacity} holds, with $C_{\rm mem}(d,s)$ chosen as in the proof. For an absolute constant $C\ge 1$,
\begin{equation}
\label{eq:compiler-ram-costs}
W_{\rm init}\le CH_0,\qquad W_{\rm tables}\le C\sum_F(m_F+L_F),\qquad W_{\rm scan}\le CK.
\end{equation}
After the shared safe-point computation, each gate parameter and scalar record append costs at most $C$ instructions, excluding the table copies counted in $W_{\rm tables}$. The output uses~\eqref{eq:compiler-record} and occupies exactly $5K+2$ cells. Input, output, and auxiliary storage together occupy at most $3265H_0$ word cells and $835H_0$ real cells.

For every $n,j\in[N]$, exact interpolation gives
\begin{equation}
\label{eq:finite-depth-cardinality}
\phi_n(X_j)=(Te_n)(X_j)=e_n(X_j)=\delta_{nj}.
\end{equation}
Fix $n\in[N]$. By~\eqref{eq:finite-depth-cardinality} and continuity, choose $\eta_n>0$ such that $\sup_{x\in B(X_n,\eta_n)}|\phi_n(x)-1|\le1/2$, and set $r_n=\frac12\min\bigl(\{1,\eta_n\}\cup\{|X_n-X_j|:j\in[N]\setminus\{n\}\}\bigr)>0$. Then
\begin{equation}
\label{eq:finite-depth-nonvanishing}
\begin{aligned}
&\varnothing\ne B(X_n,r_n)\setminus\{X_n\}\subset U,\\
&|\phi_n(x)|\ge1-|\phi_n(x)-1|\ge\tfrac12
\qquad\text{for every }x\in B(X_n,r_n).
\end{aligned}
\end{equation}

For $a,b\in U$, set $L_{2n-1}=a+\mathbb{R}(X_n-a)$ and $L_{2n}=b+\mathbb{R}(X_n-b)$ for $n\in[N]$. Each $L_\ell$ is closed and has empty interior, since $\dim L_\ell=1<d$. Starting with $B_0=B(0,1)$, choose successively nonempty open balls $B_\ell\subset B_{\ell-1}\setminus L_\ell$, $\ell\in[2N]$; each difference is nonempty and open by the preceding properties. For $z\in B_{2N}$, define
\[
\gamma(t)=
\begin{cases}
a+2t(z-a),&0\le t\le\tfrac12,\\
b+2(1-t)(z-b),&\tfrac12\le t\le1.
\end{cases}
\]
Then $\gamma\in C([0,1];\mathbb{R}^d)$, $\gamma(0)=a$, and $\gamma(1)=b$. Moreover, $\gamma(t)=X_n$ would imply $z\in L_{2n-1}\cup L_{2n}$, contrary to the choice of $z$. Hence $\gamma([0,1])\subset U$, proving that $U$ is path connected.

For $h\in C^\omega(U)$, set $A_h=\bigcap_{k=0}^{\infty}\{x\in U:D^kh(x)=0\}$. This set is relatively closed because every $D^kh$ is continuous. For $z\in A_h$, choose $\rho_z\in(0,\operatorname{dist}(z,\mathbb X))$ within the radius of convergence of the Taylor series of $h$ at $z$. Thus: for every $|v|<\rho_z$ we have
\[
h(z+v)=\sum_{k=0}^{\infty}\frac{D^kh(z)[v^k]}{k!}=0
.
\]
Consequently, $D^kh|_{B(z,\rho_z)}=0$ for every $k\ge0$, so $B(z,\rho_z)\subset A_h$. Thus $A_h$ is relatively open as well. If $h|_V=0$ for a nonempty open $V\subset U$, then $\varnothing\ne V\subset A_h$; connectedness therefore gives $A_h=U$ and $h|_U=0$.

Suppose, towards a contradiction, that $\phi_n|_U\in C^\omega(U)$ for every $n\in[N]$, and put $G_n=\{x\in U:\phi_n(x)\ne0\}$. Each $G_n$ is relatively open. If $\operatorname{int}_U(U\setminus G_n)\ne\varnothing$, the identity principle just proved gives $\phi_n|_U=0$, contrary to~\eqref{eq:finite-depth-nonvanishing}. Hence $\operatorname{int}_U(U\setminus G_n)=\varnothing$ and $\overline{G_n}^{\,U}=U$. Set $V_0=U$ and $V_n=V_{n-1}\cap G_n$ for $n\in[N]$. Since $G_n$ is open and dense in $U$, induction gives that every $V_n$ is nonempty and relatively open. Choosing $x_*\in V_N$ and using~\eqref{eq:value-depth}, we obtain the contradiction
\[
N=\#\{n\in[N]:\phi_n(x_*)\ne0\}\le\operatorname{depth}_0(T)<N.
\]

For the application to Part~III, equation~(0.5) with $\sigma\equiv0$ gives $(Tf)|_{\mathbb X}=f$. Let $S(x)\subseteq\mathbb X$ and $a_y(x)\in\mathbb{R}$ denote the sets and coefficients in equations~(0.3)-(0.4) with derivative order $\alpha=0$; these are independent of the input data. For every $x\in\mathbb{R}^d$: if $X_n\notin S(x)$ then
$\phi_n(x)=\sum_{y\in S(x)}a_y(x)e_n(y)=0$
\begin{align*}
\#\{n\in[N]:\phi_n(x)\ne0\}
&\le\#\{n\in[N]:X_n\in S(x)\}
=\#S(x)\le C_{\mathrm{dep}}(s,d).
\end{align*}
Taking the supremum over $x$ gives $\operatorname{depth}_0(T)\le C_{\mathrm{dep}}(s,d)<N$, as required.
